insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('neigebeide', 'Neigebeide', '', '', '', '', 'Neugebäude', '[{"kategorie": "allg.", "text": "historisch bedeutendes Areal im 11. Wiener Gemeindebezirk ([[Simmering]])"}, {"kategorie": "", "text": "Das Gebiet ist nach dem [[Schloss]] Neugebäude benannt, einer ehemaligen kaiserlichen Sommerresidenz, die heute als Ruine erhalten ist und als Veranstaltungsort genutzt wird"}, {"kategorie": "", "text": "Das Schloss Neugebäude wurde zwischen 1569 und 1573 unter Kaiser [[Maximilian]] II. errichtet und gilt als eines der bedeutendsten Bauwerke der Spätrenaissance in Österreich. Es wurde auf einem Gelände errichtet, das ursprünglich Teil eines Jagdgebiets war, und diente Kaiser Maximilian II. als repräsentative Sommerresidenz"}, {"kategorie": "", "text": "Trotz seiner prachtvollen Bauweise und Bedeutung wurde das Schloss Neugebäude bereits im 17. Jahrhundert zunehmend vernachlässigt, insbesondere nach dem Tod von Maximilian II. Während der Türkenbelagerung von 1683 diente es als Militärlager und erlitt schwere Schäden"}, {"kategorie": "", "text": "In den folgenden Jahrhunderten wurde das Schloss teilweise abgetragen, und das Baumaterial wurde für andere Bauprojekte in Wien verwendet, unter anderem für den Bau des Schlosses [[Schönbrunn]]. Der ursprüngliche Prunk des Schlosses Neugebäude ging somit verloren, und das Areal verfiel allmählich zu einer Ruine"}, {"kategorie": "", "text": "Heute sind nur noch Teile der ursprünglichen Anlage erhalten, darunter einige Mauern und Fundamente. Die erhaltenen Reste des Schlosses Neugebäude stehen unter Denkmalschutz und werden als Veranstaltungsort genutzt. Im Sommer finden hier Konzerte, Open-Air-Kinos und verschiedene kulturelle Veranstaltungen statt, die das historische Ambiente des Ortes nutzen."}]'::jsonb, ''),
  ('oidmaunnsduaf', 'Oidmaunnsduaf', '', '', '', '', 'Altmannsdorf', '[{"kategorie": "allg.", "text": "\"historischer Stadtteil im 12. Wiener Gemeindebezirk ([[Meidling]]), der im Südwesten von Wien liegt und an die Stadtteile [[Hetzendorf]], [[Inzersdorf]] und [[Erlaa]] im Süden grenzt\""}, {"kategorie": "", "text": "Altmannsdorf wurde erstmals im 12. Jahrhundert urkundlich erwähnt. Der Name geht auf den Personennamen „Altmann“ zurück, der wahrscheinlich ein lokaler Adliger oder Grundherr war"}, {"kategorie": "", "text": "Im 19. Jahrhundert erlebte Altmannsdorf einen Aufschwung, als Wien begann, sich immer weiter auszudehnen. 1892 wurde das einstige Dorf in den neu geschaffenen 12. Bezirk integriert. Die Verstädterung nahm zu, und Altmannsdorf wandelte sich allmählich von einem landwirtschaftlich geprägten Ort zu einem städtischen Wohngebiet"}, {"kategorie": "", "text": "Das heutige Stadtbild Altmannsdorfs ist eine Mischung aus historischen und modernen Elementen. Historisch bedeutsam ist die [[Altmannsdorfer]] Pfarrkirche St. Oswald, die im Barockstil errichtet wurde"}, {"kategorie": "", "text": "Altmannsdorf ist reich an Grünflächen, was es zu einem beliebten Wohnort für Familien und Naturliebhaber macht. Der [[Hermann-Leopoldi-Park]] im nördlichen Teil des Stadtteils und bietet weitere Erholungsmöglichkeiten."}]'::jsonb, ''),
  ('wiinabeag', 'Wiinabeag', '', '', '', '', 'Wienerberg', '[{"kategorie": "allg.", "text": "\"Bergrücken am Südrand Wiens (244m hoch)\""}, {"kategorie": "", "text": "weitläufiges Erholungsgebiet am südlichen Rand der Wiener Stadtgrenze, das sich vom 10. Bezirk ([[Favoriten]]) bis zur Grenze des 12. Bezirks ([[Meidling]]) und weiter in den 23. Bezirk ([[Liesing]]) erstreckt"}, {"kategorie": "", "text": "Das Gebiet besteht aus einer sanften Anhöhe und umfasst sowohl Wiesen und Wälder als auch Teiche und Feuchtgebiete. Der Wienerberg ist einer der letzten größeren unbebauten Naturbereiche im dicht besiedelten Süden Wiens"}, {"kategorie": "hist.", "text": "Historisch gesehen war der Wienerberg ein bedeutendes Rohstoffabbaugebiet. Bereits im 19. Jahrhundert wurde dort intensiv Lehm abgebaut, der vor allem für die Ziegelproduktion verwendet wurde. Die Wienerberger Ziegelfabriken, die in diesem Gebiet ansässig waren, waren für den Bauboom der Gründerzeit in Wien von großer Bedeutung. Die sogenannte „Ziegelböhmensiedlung“ ([[Ziaglbeem]]) und die damit verbundenen sozialen Kämpfe der Ziegelarbeiter sind ein wichtiger Teil der Wiener Arbeitergeschichte"}, {"kategorie": "", "text": "Nach dem Ende des Ziegelabbaus wurden große Teile des Wienerbergs rekultiviert und in den 1970er-Jahren als Erholungsgebiet angelegt"}]'::jsonb, ''),
  ('bruennaschdrossn', 'Brünnaschdrossn', '', '', '', '', 'Brünner Straße', '[{"kategorie": "allg.", "text": "eine der wichtigsten Ausfallstraßen im Norden Wiens, die durch den 21. Wiener Gemeindebezirk ([[Floridsdorf]]) verläuft"}, {"kategorie": "", "text": "Entlang ihres Verlaufs durch Floridsdorf führt die Brünner Straße durch verschiedene Wohngebiete, Industrie- und Gewerbegebiete sowie landwirtschaftlich geprägte Bereiche im Norden Wiens. Sie endet letztlich an der Staatsgrenze zu Tschechien und ist ein bedeutender Teil der Verbindung zwischen Wien und Brünn"}, {"kategorie": "", "text": "Die Brünner Straße ist nach der Stadt Brünn (Brno) in Tschechien benannt und hat eine lange Geschichte als Verkehrsweg zwischen Wien und den nördlichen Regionen. Historisch gesehen war sie ein wichtiger Handelsweg, der Wien mit Mähren und Böhmen verband"}, {"kategorie": "", "text": "Durch ihre zentrale Lage und Anbindung an das öffentliche Verkehrsnetz spielt sie auch für den innerstädtischen Verkehr eine entscheidende Rolle. Entlang der Straße finden sich zahlreiche Gewerbe- und Industrieunternehmen, was ihre wirtschaftliche Bedeutung zusätzlich unterstreicht."}]'::jsonb, ''),
  ('eichnschdrossn', 'Eichnschdrossn', '', '', '', '', 'Eichenstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 12. Wiener Gemeindebezirk ([[Meidling]])\""}, {"kategorie": "", "text": "Sie fungiert als zentrale Verkehrsader und verbindet verschiedene Teile des Bezirks mit wichtigen Verkehrsknotenpunkten wie dem [[Bahnhof]] Meidling und der [[Philadelphiabrücke]]"}, {"kategorie": "", "text": "Entlang der Eichenstraße befinden sich zahlreiche Geschäfte, Restaurants und Dienstleistungsbetriebe, die sie zu einem belebten städtischen Bereich machen. Insbesondere in der Nähe des Bahnhofs Meidling gibt es eine Vielzahl von Einkaufsmöglichkeiten und Einrichtungen des täglichen Bedarfs, die sowohl von Pendlern als auch von Anwohnern genutzt werden."}]'::jsonb, ''),
  ('mexikoplotz', 'Mexikoplotz', '', '', '', '', 'Mexikoplatz', '[{"kategorie": "allg.", "text": "\"bekannter Platz im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), in unmittelbarer Nähe zum [[Donaukanal]] und dem [[Reichsbrücke-Brückenkopf]]\""}, {"kategorie": "hist.", "text": "Der Mexikoplatz erhielt seinen Namen im Jahr 1956 als Zeichen der Dankbarkeit für die Unterstützung Mexikos während der nationalsozialistischen Besetzung Österreichs. Mexiko war eines der wenigen Länder, das 1938 offiziell gegen den Anschluss Österreichs an das nationalsozialistische Deutschland protestierte. Dieser symbolische Akt der Solidarität führte dazu, dass der Platz, der bis dahin Erzherzog-Karl-Platz hieß, in Mexikoplatz umbenannt wurde"}, {"kategorie": "", "text": "Das herausragende Bauwerk am Mexikoplatz ist die [[Pfarrkirche]] Franz von Assisi, die oft als \"Mexikokirche\" bezeichnet wird. Diese imposante Kirche im neoromanischen Stil wurde zwischen 1898 und 1910 anlässlich des 50-jährigen Thronjubiläums von Kaiser Franz Joseph I. errichtet und ist ein markantes Wahrzeichen im Nordosten Wiens"}, {"kategorie": "", "text": "Die Gegend um den Mexikoplatz ist durch ihre multikulturelle Bevölkerung geprägt, was sich in einer Vielfalt an Geschäften und Lokalen widerspiegelt. Der Platz dient als Treffpunkt für Menschen unterschiedlicher Nationalitäten und bietet durch seine Nähe zur [[Donau]] und den Grünflächen am Donauufer auch Erholungsmöglichkeiten."}]'::jsonb, ''),
  ('mexikokiachn', 'Mexikokiachn', '', '', '', '', 'Mexikokirche', '[{"kategorie": "allg.", "text": "\"beeindruckende römisch-katholische Kirche im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), direkt am [[Mexikoplatz]] nahe der [[Donau]] (offizieller Name: \"Pfarrkirche Franz von Assisi\")\""}, {"kategorie": "", "text": "Sie ist eines der markantesten Bauwerke im Nordosten Wiens und ein bedeutendes Wahrzeichen der Stadt"}, {"kategorie": "", "text": "Die Pfarrkirche Franz von Assisi wurde zwischen 1898 und 1910 erbaut. Anlass für den Bau war das 50-jährige Regierungsjubiläum von Kaiser Franz Joseph I., weshalb die Kirche ursprünglich auch als \"Kaiserjubiläumskirche\" bezeichnet wurde"}, {"kategorie": "", "text": "Der Architekt der Kirche war Victor Luntz, der sich beim Design an romanischen Baustilen orientierte und die Kirche mit mächtigen Rundbögen, Türmen und einem [[Rosettenfenster]] gestaltete. Die Kirche zeichnet sich durch ihre massiven, roten Türme und ihre großen, ornamentierten Fassaden aus. Die Hauptkuppel der Kirche erhebt sich zentral über dem Bauwerk und wird von vier kleineren Türmen flankiert. Besonders auffällig sind der Hauptturm und die zwei flankierenden Türme, die der Kirche ihre markante Silhouette verleihen"}, {"kategorie": "", "text": "Die Kirche ist dem heiligen Franz von Assisi gewidmet, einem der bekanntesten Heiligen der römisch-katholischen Kirche und Gründer des Franziskanerordens. Franz von Assisi, der im 12. und 13. Jahrhundert lebte, ist bekannt für seine Bescheidenheit, seine Liebe zur Natur und seine Hingabe an die Armen und Bedürftigen"}, {"kategorie": "", "text": "Die Pfarrkirche Franz von Assisi ist eine aktive Pfarrkirche. Neben den regulären Messen finden in der Kirche auch Hochzeiten, Taufen und andere kirchliche Zeremonien statt. Die Kirche bietet zudem Raum für gemeindliche Aktivitäten, darunter soziale und karitative Projekte, die besonders in einem multikulturellen Bezirk wie der Leopoldstadt von großer Bedeutung sind."}]'::jsonb, ''),
  ('franziskaanakloosta', 'Franziskaanakloosta', '', '', '', '', 'Franziskaner Kloster', '[{"kategorie": "allg.", "text": "historisches Kloster im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Es befindet sich direkt am [[Franziskanerplatz]], neben der [[Franziskanerkirche]] St. Hieronymus, und gehört dem Orden der [[Franziskaner]] an"}, {"kategorie": "", "text": "Das Franziskanerkloster wurde zusammen mit der Franziskanerkirche im frühen 17. Jahrhundert gegründet. Die Franziskaner kamen bereits im 13. Jahrhundert nach Wien, aber erst 1603 begann der Bau des heutigen Klosters, als die Ordensgemeinschaft eine feste Niederlassung in der Stadt errichtete"}, {"kategorie": "", "text": "Das Kloster hat in seiner langen Geschichte viele bedeutende Ereignisse miterlebt, darunter die Türkenbelagerungen und die politischen und religiösen Umwälzungen der Reformationszeit und der Gegenreformation. Trotz der Wirren dieser Zeit blieb das Kloster immer ein bedeutender Ort des Glaubens und der Seelsorge in Wien"}, {"kategorie": "", "text": "Das Franziskanerkloster ist ein weitläufiger Gebäudekomplex, der sich um die Franziskanerkirche gruppiert. Die schlichte und zurückhaltende Architektur des Klosters passt zu den Idealen des Franziskanerordens, der sich durch Bescheidenheit und Einfachheit auszeichnet. Die Fassade des Klosters wirkt unauffällig und fügt sich harmonisch in das historische Stadtbild ein"}, {"kategorie": "", "text": "Das Kloster verfügt auch über eine Bibliothek, die wertvolle religiöse Schriften und historische Dokumente enthält. Einige dieser Dokumente stammen aus den frühen Jahren des Klosters und sind von großem kulturellem und religiösem Wert"}, {"kategorie": "", "text": "Das Franziskanerkloster wird bis heute von Franziskanermönchen bewohnt und genutzt. Die Franziskaner leben nach den Regeln des Heiligen Franz von Assisi, der den Orden im 13. Jahrhundert gegründet hat. Diese Regeln beinhalten Armut, Bescheidenheit und die Hingabe an Gott und den Dienst an den Menschen."}]'::jsonb, ''),
  ('mosesbrunnan', 'Mosesbrunnan', '', '', '', '', 'Mosesbrunnen', '[{"kategorie": "allg.", "text": "\"historischer Brunnen auf dem Franziskanerplatz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Er gehört zu den ältesten Brunnen Wiens und ist ein bemerkenswertes Beispiel barocker Brunnenkunst. Der Brunnen wird oft nach seiner zentralen Figur, dem biblischen Propheten Moses, benannt, der auf einer eindrucksvollen Statue dargestellt ist"}, {"kategorie": "", "text": "Der Mosesbrunnen wurde im 17. Jahrhundert errichtet, als die Stadt Wien in großem Maße barocke Bauwerke und Kunstwerke schuf. Er wurde 1798 von dem Bildhauer Johann Martin Fischer geschaffen und steht seitdem auf dem [[Franziskanerplatz]], einem ruhigen und historisch bedeutenden Platz in der Wiener Altstadt"}, {"kategorie": "", "text": "Die zentrale Figur des Brunnens stellt den Propheten Moses dar, der in der Bibel als Führer des Volkes Israel bekannt ist. Moses wird auf dem Brunnen in einer majestätischen Pose dargestellt, in der er mit einem Stab auf einen Felsen schlägt, um Wasser hervorsprudeln zu lassen. Dies bezieht sich auf eine Episode im Alten Testament, bei der Moses auf Gottes Geheiß Wasser aus einem Felsen hervorbringt, um das dürstende Volk Israel in der Wüste zu versorgen (Buch Exodus, Kapitel 17)"}, {"kategorie": "", "text": "Umgeben ist die Moses-Statue von einem Wasserbecken, das von schlichten, eleganten Verzierungen im barocken Stil geprägt ist. Der Brunnen symbolisiert die göttliche Versorgung und ist eine Metapher für das Leben spendende Wasser, das im Christentum oft für spirituelle Erneuerung steht."}]'::jsonb, ''),
  ('ziakusgossn', 'Ziakusgossn', '', '', '', '', 'Zirkusgasse', '[{"kategorie": "allg.", "text": "\"Straße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), die sich durch ihre zentrale Lage und ihre historische Bedeutung auszeichnet\""}, {"kategorie": "", "text": "Sie verläuft parallel zum [[Donaukanal]] und verbindet die Gegend um den [[Prater]] mit der Innenstadt"}, {"kategorie": "", "text": "Die Zirkusgasse erhielt ihren Namen im Jahr 1862 in Erinnerung an den Circus Gymnasticus, den ersten festen Zirkusbau Wiens, der sich in dieser Gegend befand. Der Circus Gymnasticus wurde 1808 von Christoph de Bach, einem Zirkusdirektor und Akrobaten, gegründet und war eine bedeutende kulturelle Institution in Wien. Der Zirkus war berühmt für seine Aufführungen und zog viele Besucher an. Später wurde der Zirkus in das Carltheater umgewandelt, das ebenfalls eine zentrale Rolle im Wiener Kulturleben spielte"}, {"kategorie": "", "text": "Die Zirkusgasse und ihre Umgebung waren während des 19. und 20. Jahrhunderts Teil eines florierenden jüdischen Viertels, und viele Gebäude in der Gegend waren von jüdischen Kaufleuten und Handwerkern bewohnt. Während des Zweiten Weltkriegs erlitt die Gegend schwere Verluste durch die Vertreibung und Deportation der jüdischen Bevölkerung, was die Zirkusgasse zu einem historischen Ort macht, der eng mit der jüdischen Geschichte Wiens verbunden ist."}]'::jsonb, ''),
  ('fiakaplotz', 'Fiakaplotz', '', '', '', '', 'Fiakerplatz', '[{"kategorie": "allg.", "text": "\"beschaulicher Platz im 3. Wiener Gemeindebezirk ([[Landstraße]]), genauer im Stadtteil [[Erdberg]]\""}, {"kategorie": "", "text": "Er ist benannt nach dem \"Fiakerdörfel\", dem einstigen Wohnsitz vieler Wiener [[Fiaker]]"}, {"kategorie": "", "text": "Der Name des Platzes ehrt diese Tradition und die Fiaker, die ein fester Bestandteil der Wiener Kultur und Geschichte sind."}]'::jsonb, ''),
  ('schnoebaun', 'Schnöbaun', '', '', '', '', 'Schnellbahn', '[{"kategorie": "allg.", "text": "städtisches Nahverkehrssystem der Stadt Wien und ihres Umlandes, das insbesondere die Stadt mit den umliegenden Regionen in Niederösterreich und dem Burgenland verbindet (oft auch als [[S-Bahn Wien]] bezeichnet)"}, {"kategorie": "", "text": "Die Wiener Schnellbahn ist ein elektrisch betriebenes Eisenbahnsystem, das auf bestehenden Eisenbahnstrecken der ÖBB (Österreichische Bundesbahnen) verkehrt. Sie stellt schnelle Verbindungen zwischen den außerhalb gelegenen Bezirken und Vororten Wiens und der Innenstadt her und ist damit ein zentrales Verkehrsmittel für Pendler, die täglich in die Stadt und wieder hinausfahren. Neben der Erschließung des Wiener Stadtgebiets verbindet die Schnellbahn Wien mit Städten und Gemeinden in den angrenzenden Bundesländern"}, {"kategorie": "", "text": "Das Schnellbahnnetz in Wien besteht aus mehreren S-Bahn-Linien, die mit einem „S“ und einer Nummer gekennzeichnet sind, z. B. S1, S2, S3 und S7. Jede dieser Linien bedient unterschiedliche Strecken"}, {"kategorie": "", "text": "Das Wiener S-Bahn-Netz wurde 1954 ins Leben gerufen, um Wien besser mit den Vororten zu verknüpfen. Ursprünglich hieß das System „Schnellbahn“, der Begriff „S-Bahn“ wurde später verbreiteter"}, {"kategorie": "", "text": "Die S45 ist eine Querverbindung innerhalb der Stadt, auch als [[Vorortelinie]] bekannt, die ohne das Stadtzentrum zu berühren mehrere wichtige Außenbezirke miteinander verbindet."}]'::jsonb, ''),
  ('voaoatelinii', 'Voaoatelinii', '', '', '', '', 'Vorortelinie', '[{"kategorie": "allg.", "text": "\"S-Bahn-Linie im Wiener Schnellbahnnetz, die eine Querverbindung durch die Wiener Außenbezirke herstellt, ohne das Stadtzentrum zu durchqueren (auch bekannt als \"S45\")\""}, {"kategorie": "", "text": "Die Vorortelinie spielt eine wichtige Rolle im öffentlichen Nahverkehr der Stadt, da sie mehrere Stadtteile und Bahnhöfe im Westen und Norden Wiens verbindet"}, {"kategorie": "", "text": "Sie verläuft von [[Hütteldorf]] im Westen Wiens, wo sie Anschluss an die U-Bahn-Linie U4 und die Westbahnstrecke hat, bis zum [[Handelskai]], einem wichtigen Knotenpunkt, der Anschluss an die U-Bahn-Linie U6 und die S-Bahn-Linien entlang der [[Donau]] bietet. Die Linie verläuft entlang eines historischen Bahnkorridors und führt durch die Wiener Außenbezirke, wo sie zahlreiche wichtige Stationen bedient"}, {"kategorie": "", "text": "Die Vorortelinie hat eine lange Geschichte, die bis ins 19. Jahrhundert zurückreicht. Sie wurde als Gürtelbahn konzipiert, um die Vororte von Wien miteinander zu verbinden und den Güterverkehr rund um die Stadt zu erleichtern. Der Personenverkehr auf der Vorortelinie wurde ab 1898 aufgenommen. Nach dem Zweiten Weltkrieg verlor die Strecke zeitweise an Bedeutung, wurde jedoch in den 1980er Jahren wieder reaktiviert und als S-Bahn-Linie S45 in das Wiener Schnellbahnnetz integriert."}]'::jsonb, ''),
  ('liisingboch', 'Liisingboch', '', '', '', '', 'Liesingbach', '[{"kategorie": "allg.", "text": "\"Bach in Wien, der eine Länge von etwa 30 Kilometern hat und den 23. Bezirk ([[Liesing]]) durchquert, nach dem er auch benannt ist\""}, {"kategorie": "", "text": "Er entspringt im Wienerwald in Niederösterreich, fließt durch den südlichen Teil Wiens und mündet in die Schwechat, die wiederum in die Donau fließt"}, {"kategorie": "", "text": "Der Bach durchzieht die Bezirke Liesing und [[Favoriten]] und bildet in einigen Abschnitten die Grenze zwischen städtischem Wohnraum und Grünflächen"}, {"kategorie": "", "text": "In der Vergangenheit war der Liesingbach stark reguliert, um Hochwassergefahren zu minimieren. In den letzten Jahren wurden jedoch Renaturierungsprojekte durchgeführt, um dem Bach seinen natürlichen Charakter zurückzugeben."}]'::jsonb, ''),
  ('hetznduaf', 'Hetznduaf', '', '', '', '', 'Hetzendorf', '[{"kategorie": "allg.", "text": "\"Stadtteil im 12. Gemeindebezirk ([[Meidling]]) im Südwesten von Wien\""}, {"kategorie": "", "text": "Es handelt sich um ein historisches Viertel, das durch seine Mischung aus Wohngebieten, Grünflächen und historischen Bauten geprägt ist"}, {"kategorie": "", "text": "Hetzendorf wurde erstmals im 12. Jahrhundert urkundlich erwähnt, war ursprünglich ein kleines Dorf und dann eine eigenständige Ortschaft, die 1892 nach Wien eingemeindet wurde"}, {"kategorie": "", "text": "Hetzendorf ist ein historisch geprägter Stadtteil, der für seine Ruhe, seine Grünflächen und das [[Schloss]] Hetzendorf und die gleichnamige Modeschule, sowie die [[Pfarrkirche]] Hetzendorf und seine gute Anbindung ans Stadtzentrum bekannt ist."}]'::jsonb, ''),
  ('gaudenzduaf', 'Gaudenzduaf', '', '', '', '', 'Gaudenzdorf', '[{"kategorie": "allg.", "text": "Stadtteil im 12. Wiener Gemeindebezirk ([[Meidling]]), der bis zur Eingemeindung nach Wien im Jahr 1892 eine eigenständige Gemeinde war"}, {"kategorie": "", "text": "Der Stadtteil liegt im Norden des Bezirks und erstreckt sich entlang des rechten Ufers des [[Wienflusses]]. Gaudenzdorf ist heute ein dicht bebautes urbanes Gebiet und Teil des stark urbanisierten Meidling"}, {"kategorie": "", "text": "Gaudenzdorf wurde im 18. Jahrhundert gegründet und war zunächst ein kleines Dorf vor den Toren Wiens. Es entwickelte sich durch die Industrialisierung im 19. Jahrhundert schnell zu einem urbanen Gebiet. Die Lage entlang des Wienflusses begünstigte die Ansiedlung von Fabriken und Handwerksbetrieben, was den wirtschaftlichen Aufschwung der Gegend förderte. Der Name \"Gaudenzdorf\" stammt wahrscheinlich von einem Vorbesitzer der Ländereien, Gaudentius Andreas Dunkler, einem Wiener Stadtrichter."}]'::jsonb, ''),
  ('philadelphiabruckn', 'Philadelphiabruckn', '', '', '', '', 'Philadelphiabrücke', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsbrücke im 12. Wiener Gemeindebezirk ([[Meidling]]), welche die Südbahnstrecke überquert und wichtige Teile des Bezirks miteinander verbindet"}, {"kategorie": "", "text": "Zudem ist sie ein wichtiger Verkehrsknotenpunkt sowohl für den öffentlichen Nahverkehr als auch für den Individualverkehr in Wien. Die Brücke ist nach der Stadt Philadelphia in den USA benannt und liegt in unmittelbarer Nähe des Bahnhofs Wien Meidling"}, {"kategorie": "", "text": "Die Philadelphiabrücke erhielt ihren Namen im Jahr 1955 im Rahmen der \"Wiener Brückenbenennung\". Der Name soll die Verbundenheit und Freundschaft zwischen Wien und der Stadt Philadelphia in den USA symbolisieren"}, {"kategorie": "", "text": "Die Philadelphiabrücke ist sowohl für den Autoverkehr als auch für den öffentlichen Verkehr ausgelegt. Sie verfügt über mehrere Fahrspuren für den Straßenverkehr sowie über eigene Trassen für die Straßenbahnen und Busse"}, {"kategorie": "", "text": "Darüber hinaus befindet sich bei der Brücke auch der [[Bahnhof]] Wien Meidling, der als einer der wichtigsten Bahnhöfe Wiens viele nationale und internationale Zugverbindungen bedient. Der Bahnhof ist auch ein wichtiger Knotenpunkt für die Wiener [[S-Bahn-Linien]], die das Stadtzentrum mit den Vororten und dem Wiener Umland verbinden."}]'::jsonb, ''),
  ('geaschdhof', 'Geaschdhof', '', '', '', '', 'Gersthof', '[{"kategorie": "allg.", "text": "\"Stadtteil im 18. Wiener Gemeindebezirk ([[Währing]]) im Nordwesten von Wien\""}, {"kategorie": "", "text": "Gersthof hat eine lange Geschichte, die bis ins Mittelalter zurückreicht, und zeichnet sich durch seine elegante Architektur, zahlreiche Grünflächen und gute Anbindung an den öffentlichen Verkehr aus"}, {"kategorie": "", "text": "Der Name Gersthof geht auf ein Gut zurück, das erstmals im 14. Jahrhundert als \"Gerstlehof\" urkundlich erwähnt wurde. Es entwickelte sich zunächst zu einem kleinen Dorf und später, im Zuge der Wiener Stadterweiterung, zu einem Teil des urbanen Gebiets. Im 19. Jahrhundert wurde Gersthof durch den Ausbau der Verkehrsverbindungen und die Errichtung von Villen zu einem begehrten Wohnort für wohlhabende Wiener Familien"}, {"kategorie": "", "text": "Gersthof wurde 1892 im Zuge der Eingemeindung der Vororte nach Wien in den Bezirk [[Währing]] integriert"}]'::jsonb, ''),
  ('gentzgossn', 'Gentzgossn', '', '', '', '', 'Gentzgasse', '[{"kategorie": "allg.", "text": "bedeutende Verkehrs- und Wohnstraße im 18. Wiener Gemeindebezirk ([[Währing]])"}, {"kategorie": "", "text": "Die Gentzgasse beginnt im Westen an der Kreuzung mit der [[Währinger]] Straße und erstreckt sich in östlicher Richtung bis zur [[Simonygasse]], wo sie in den Stadtteil [[Gersthof]] übergeht. Sie verläuft durch das zentrale Wohngebiet von Währing und kreuzt dabei mehrere wichtige Straßen des Bezirks, wie die [[Kreuzgasse]] und die [[Schulgasse]]"}, {"kategorie": "", "text": "Die Gentzgasse ist nach Moritz Ritter von Gentz benannt, einem Wiener Beamten und k.k. Regierungsrat, der im 19. Jahrhundert lebte. Der Name der Straße wurde im Rahmen der Expansion Wiens im späten 19. Jahrhundert vergeben, als Währing stärker in die städtische Infrastruktur eingebunden wurde"}, {"kategorie": "", "text": "Die Gentzgasse ist eine belebte Geschäftsstraße, besonders in den unteren Abschnitten nahe der Währinger Straße. Hier befinden sich viele Einzelhandelsgeschäfte, Supermärkte, Apotheken, Bäckereien und Dienstleistungsbetriebe"}, {"kategorie": "", "text": "In den oberen Abschnitten der Gentzgasse, näher an [[Gersthof]], dominieren Wohnhäuser, viele davon aus der Zeit der [[Gründerzeit]], die für ihre architektonischen Details bekannt sind"}]'::jsonb, ''),
  ('heabeckschdrossn', 'Heabeckschdrossn', '', '', '', '', 'Herbeckstraße', '[{"kategorie": "allg.", "text": "bedeutende Straße im Westen Wiens, die sich vom 17. Bezirk ([[Hernals]]) bis in den 18. Bezirk ([[Währing]]) erstreckt"}, {"kategorie": "", "text": "Sie ist nach Joseph Herbeck, einem österreichischen Dirigenten und Komponisten des 19. Jahrhunderts, benannt, der für seine Rolle in der Wiener Musikkultur bekannt war, insbesondere als Förderer von Anton Bruckner"}, {"kategorie": "", "text": "Im 17. Bezirk ([[Hernals]]) dominieren noch stark die [[Gründerzeithäuser]]. Diese Bauten sind typisch für die Wiener Stadtteile, die während der industriellen Expansion Wiens im späten 19. Jahrhundert errichtet wurden. Diese Wohnhäuser sind meist mehrstöckig und zeichnen sich durch aufwendige Stuckverzierungen und hohe Fenster aus"}, {"kategorie": "", "text": "Im 18. Bezirk ([[Währing]]) ändert sich die Bebauung deutlich: Hier finden sich viele Villen und modernere Wohnbauten. Die Straßen in Währing sind oft breiter, und es gibt mehr Grünflächen, die das Straßenbild auflockern. Das [[Cottage-Viertel]], ein exklusives Wohngebiet im 18. Bezirk, liegt nicht weit von der Herbeckstraße entfernt und ist für seine schönen Villen bekannt."}]'::jsonb, ''),
  ('simonygossn', 'Simonygossn', '', '', '', '', 'Simonygasse', '[{"kategorie": "allg.", "text": "\"relativ kurze Wohnstraße, die durch den 18. Wiener Gemeindebezirk ([[Währing]]) verläuft\""}, {"kategorie": "", "text": "Sie ist nach dem österreichischen Alpenforscher Friedrich Simony (1813–1896) benannt. Simony war ein bedeutender Geograf und Gletscherforscher, der maßgeblich zur Erschließung des Dachsteingebirges beigetragen hat"}, {"kategorie": "", "text": "Die Simonygasse liegt in einem Wohngebiet des 18. Bezirks, beginnt bei der [[Kreuzgasse]] und mündet im Norden in die [[Gentzgasse]]"}, {"kategorie": "", "text": "Sie zeichnet sich durch ihre charmante Architektur, bestehend aus Gründerzeitbauten und modernen Wohnhäusern, sowie durch ihre Nähe zu wichtigen Verkehrsverbindungen und Erholungsgebieten wie dem [[Türkenschanzpark]] oder dem [[Pötzleinsdorfer]] Schlosspark aus."}]'::jsonb, ''),
  ('kreizgossn', 'Kreizgossn', '', '', '', '', 'Kreuzgasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 18. Wiener Gemeindebezirk ([[Währing]])\""}, {"kategorie": "", "text": "Sie erstreckt sich in nord-südlicher Richtung, verbindet verschiedene Wohn- und Geschäftsviertel und spielt eine zentrale Rolle im Verkehrsnetz dieses Bezirks"}, {"kategorie": "", "text": "Die Straße ist Teil eines gut entwickelten städtischen Gebiets und zeichnet sich durch eine Mischung aus Wohnhäusern, Geschäften und Bildungseinrichtungen aus"}, {"kategorie": "", "text": "Die [[Gründerzeithäuser]] entlang der Kreuzgasse prägen das Straßenbild, vor allem im nördlichen Teil der Straße, wo die Bebauung dichter ist. Weiter südlich in Richtung [[Martinstraße]] findet man moderne Wohnbauten und einige neue Entwicklungen, die das städtische Bild ergänzen"}, {"kategorie": "", "text": "Mit ihrer guten Verkehrsanbindung, den zahlreichen Geschäften und Restaurants sowie der Nähe zu großen Erholungsgebieten wie dem [[Türkenschanzpark]] ist die Kreuzgasse ein lebendiger Teil von Währing, der sowohl für Anwohner als auch für Besucher attraktiv ist."}]'::jsonb, ''),
  ('schuigossn', 'Schuigossn', '', '', '', '', 'Schulgasse', '[{"kategorie": "allg.", "text": "\"zentrale Wohnstraße im 18. Wiener Gemeindebezirk ([[Währing]]), die sich über eine relativ lange Strecke durch das Wohn- und Geschäftsgebiet dieses Bezirks erstreckt\""}, {"kategorie": "", "text": "Sie ist eine typische Wiener Straße mit einer Mischung aus Wohngebäuden, Geschäften und öffentlichen Einrichtungen, darunter auch Schulen bzw. Bildungseinrichtungen, wobei die Straße - historisch gesehen - nach drei, hier einst gelegenen Schulen benannt wurde"}, {"kategorie": "", "text": "Die Bebauung entlang der Schulgasse ist geprägt von einer Mischung aus Gründerzeitbauten, die typisch für diesen Teil Wiens sind, und moderneren Wohnhäusern. Die historischen Gebäude stammen aus der Zeit der raschen Stadterweiterung Wiens im späten 19. Jahrhundert und zeichnen sich durch dekorative Fassaden und großzügige Raumhöhen aus"}, {"kategorie": "", "text": "Die Schulgasse liegt in der Nähe einiger der wichtigsten Erholungsgebiete im 18. Bezirk. Besonders erwähnenswert ist der [[Türkenschanzpark]], der nur wenige Minuten entfernt liegt. Auch der [[Währinger]] Park und der [[Pötzleinsdorfer]] Schlosspark befinden sich in der weiteren Umgebung und sind wichtige Naherholungsgebiete für die Anwohner der Schulgasse."}]'::jsonb, ''),
  ('tueaknschaunzpark', 'Tüaknschaunzpark', '', '', '', '', 'Türkenschanzpark', '[{"kategorie": "allg.", "text": "einer der größten und bekanntesten Parks im 18. Wiener Gemeindebezirk ([[Währing]])"}, {"kategorie": "", "text": "Er liegt im Nordwesten Wiens und erstreckt sich über eine Fläche von rund 150.000 Quadratmetern"}, {"kategorie": "", "text": "Der Park ist nicht nur ein beliebtes Naherholungsgebiet, sondern auch von historischer und kultureller Bedeutung, da er an die Türkenkriege des 16. und 17. Jahrhunderts erinnert, nach denen er benannt wurde"}, {"kategorie": "", "text": "Der Türkenschanzpark wurde Ende des 19. Jahrhunderts auf einem Gebiet angelegt, das im Zuge der zweiten Türkenbelagerung Wiens 1683 von osmanischen Truppen als Lager genutzt worden sein soll. Der Name \"Türkenschanz\" verweist auf diese historische Verbindung. 1885 wurde der Park von dem berühmten Wiener Stadtgärtner Rudolf Siebeck gestaltet und 1888 offiziell eröffnet"}, {"kategorie": "", "text": "Der Türkenschanzpark ist für seine hügelige Landschaft, Wasserfälle, Teiche und dichte Baumbestände bekannt. Die Gestaltung des Parks erinnert an englische Landschaftsgärten und kombiniert natürliche Gegebenheiten mit sorgfältig angelegten Spazierwegen und Erholungsflächen. Es gibt eine Vielzahl von exotischen Pflanzenarten und alte, prächtige Bäume, was den Park zu einem beliebten Ziel für Naturliebhaber macht."}]'::jsonb, ''),
  ('gymnasiumschdrossn', 'Gymnasiumschdrossn', '', '', '', '', 'Gymnasiumstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 18. Wiener Gemeindebezirk ([[Währing]])\""}, {"kategorie": "", "text": "Sie ist benannt (1877 in Oberdöbling) nach dem Döblinger Gymnasium (gegründet 1885, seit 1887 im neuen Gebäude Nummer 37)"}, {"kategorie": "", "text": "Sie verläuft durch ein ruhiges Wohngebiet und ist in der Nähe des [[Währinger]] Parks und des [[Türkenschanzparks]] gelegen"}, {"kategorie": "", "text": "Die Bebauung entlang der Gymnasiumstraße besteht hauptsächlich aus Wohnhäusern der [[Gründerzeit]] und dem frühen 20. Jahrhundert. Die Mehrfamilienhäuser sind meist mehrstöckig und bieten eine typische Wiener Architektur mit verzierten Fassaden und großzügigen Innenhöfen. In der Umgebung gibt es auch modernere Wohngebäude, die die historische Architektur ergänzen"}, {"kategorie": "", "text": "Ihre Lage in einem der grüneren Bezirke Wiens macht sie besonders attraktiv für Familien und Menschen, die eine städtische Umgebung mit Nähe zu Bildungseinrichtungen und Erholungsgebieten schätzen."}]'::jsonb, ''),
  ('schumanngossn', 'Schumanngossn', '', '', '', '', 'Schumanngasse', '[{"kategorie": "allg.", "text": "\"zentrale, belebte Straße im 18. Wiener Gemeindebezirk ([[Währing]]), die sich durch mehrere Wohn- und Geschäftsgebiete zieht\""}, {"kategorie": "", "text": "Sie wurde nach dem berühmten deutschen Komponisten Robert Schumann (1810–1856) benannt, der für seine Werke in der Romantik bekannt ist"}, {"kategorie": "", "text": "Die Bebauung entlang der Schumanngasse besteht hauptsächlich aus mehrstöckigen Wohnhäusern, die im typischen Wiener Baustil des 19. und frühen 20. Jahrhunderts errichtet wurden. Diese Gebäude zeichnen sich durch verputzte Fassaden, oft mit Stuckverzierungen, und hohe Decken aus. Der architektonische Stil spiegelt den historischen Charakter der Straße wider, die während der Wiener Stadterweiterung entwickelt wurde"}, {"kategorie": "", "text": "Die Schumanngasse liegt zudem auch nahe dem [[Währinger]] Park und dem [[Türkenschanzpark]], zwei beliebten Naherholungsgebieten im Bezirk."}]'::jsonb, ''),
  ('martinschdrossn', 'Martinschdrossn', '', '', '', '', 'Martinstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 18. Wiener Gemeindebezirk ([[Währing]]), die sich durch ein gut erschlossenes Wohngebiet erstreckt\""}, {"kategorie": "", "text": "Die Martinstraße ist vorwiegend von Wohngebäuden geprägt, die aus verschiedenen Epochen stammen, darunter viele aus der [[Gründerzeit]]. Diese mehrstöckigen Gebäude zeichnen sich durch hohe Decken, verzierten Fassaden und Innenhöfe aus, die für das typische Wiener Stadtbild stehen. Es gibt auch einige modernere Wohnbauten, die in den letzten Jahrzehnten hinzugekommen sind, wodurch eine interessante architektonische Mischung entsteht"}, {"kategorie": "", "text": "Die Martinstraße profitiert von ihrer Nähe zu mehreren Grünflächen und Parks. Der nahe gelegene [[Währinger]] Park bietet zahlreiche Freizeitmöglichkeiten und lädt zu Spaziergängen und sportlichen Aktivitäten ein. Auch der etwas weiter entfernte [[Türkenschanzpark]], einer der größten Parks in Wien, ist gut erreichbar und bietet zusätzliche Möglichkeiten zur Erholung im Grünen."}]'::jsonb, ''),
  ('neilreichgossn', 'Neilreichgossn', '', '', '', '', 'Neilreichgasse', '[{"kategorie": "allg.", "text": "belebte und zentrale Straße im 10. Wiener Gemeindebezirk ([[Favoriten]])"}, {"kategorie": "", "text": "Sie verläuft in süd-nördlicher Richtung und verbindet verschiedene Wohn- und Geschäftsgebiete des Bezirks"}, {"kategorie": "", "text": "Die Straße wurde nach Johann Baptist Neilreich (1796–1871) benannt, einem bedeutenden österreichischen Botaniker. Neilreich war bekannt für seine botanischen Forschungen und seine detaillierten Studien über die Flora des österreichischen Kaiserreichs. Seine Arbeiten hatten einen nachhaltigen Einfluss auf die botanische Wissenschaft in Mitteleuropa"}, {"kategorie": "", "text": "Mit ihrer Mischung aus Wohnhäusern und Nahversorgungsmöglichkeiten ist sie ein wichtiger Bestandteil des städtischen Lebens in Favoriten."}]'::jsonb, ''),
  ('billrothschdrossn', 'Billrothschdrossn', '', '', '', '', 'Billrothstraße', '[{"kategorie": "allg.", "text": "zentrale Verkehrs- und Wohnstraße im 19. Wiener Gemeindebezirk ([[Döbling]])"}, {"kategorie": "", "text": "Sie ist nach dem berühmten österreichischen Chirurgen Theodor Billroth (1829–1894) benannt, der ein Pionier der modernen Chirurgie war und bedeutende Fortschritte in der Bauchchirurgie machte"}, {"kategorie": "", "text": "Die Billrothstraße verläuft von der [[Nussdorfer]] Lände (nahe dem [[Donaukanal]]) im Süden in nordwestlicher Richtung durch den Bezirk Döbling und endet in der Nähe des [[Döblinger]] Friedhofs"}, {"kategorie": "", "text": "Die Bebauung entlang der Billrothstraße ist vielfältig. Der südliche Abschnitt ist vorwiegend durch [[Gründerzeitbauten]] geprägt, die für Wien charakteristisch sind. Diese Gebäude sind meist mehrstöckige Wohnhäuser mit verzierten Fassaden. Im nördlichen Bereich gibt es modernere Wohnanlagen sowie einige Einfamilienhäuser und Villen, die die Nähe zur Natur im Grünen hervorheben"}, {"kategorie": "", "text": "Ihre gute Verkehrsanbindung, die Vielfalt an Wohngebäuden und die Mischung aus Geschäften, Schulen und medizinischen Einrichtungen machen sie zu einem bedeutenden Teil des Bezirks."}]'::jsonb, ''),
  ('krottnbochschdrossn', 'Krottnbochschdrossn', '', '', '', '', 'Krottenbachstraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 19. Wiener Gemeindebezirk ([[Döbling]]), die sich in einem der gehobeneren Wohnviertel Wiens befindet\""}, {"kategorie": "", "text": "Sie verläuft in nordöstlicher Richtung durch mehrere Stadtteile von Döbling, darunter die bekannten Wohngebiete [[Oberdöbling]], [[Neustift]] am Walde und [[Salmannsdorf]]"}, {"kategorie": "", "text": "Der heutige Name bezieht sich auf den seit 1908 eingewölbten Krottenbach, dessen Tal die Straße folgt"}, {"kategorie": "", "text": "Die Bebauung entlang der Krottenbachstraße ist vielfältig und spiegelt den Charakter des 19. Bezirks wider, der sowohl städtische als auch ländliche Elemente vereint. In den unteren Abschnitten der Straße gibt es viele mehrstöckige Wohnhäuser, während in den oberen, ruhigeren Teilen der Straße vor allem Einfamilienhäuser und Villen dominieren. Die Nähe zum [[Wienerwald]] verleiht den höher gelegenen Bereichen der Krottenbachstraße einen fast ländlichen Charakter."}]'::jsonb, ''),
  ('agnesgossn', 'Agnesgossn', '', '', '', '', 'Agnesgasse', '[{"kategorie": "allg.", "text": "\" ruhige Wohnstraße im 19. Wiener Gemeindebezirk ([[Döbling]]), einem der gehobenen Bezirke im Nordwesten Wiens\""}, {"kategorie": "", "text": "Sie liegt in einem grünen und ruhigen Teil des Bezirks und führt durch eines der attraktiven Wohngebiete in Döbling, das von der Nähe zum [[Wienerwald]] und zu den Weingärten des Bezirks profitiert"}, {"kategorie": "", "text": "Entlang der Agnesgasse befinden sich hauptsächlich Einfamilienhäuser, moderne Villen und einige historische Gebäude, die den gehobenen Wohncharakter der Gegend widerspiegeln"}, {"kategorie": "", "text": "Die Umgebung der Agnesgasse ist geprägt von viel Grün, Parks und Erholungsflächen, darunter der nahe gelegene [[Wienerwald]] und die Weinberge, die für Spaziergänge und Wanderungen einladen. Die Nähe zum Heurigenviertel in [[Neustift]] am Walde macht die Gegend besonders attraktiv für Menschen, die das traditionelle Wiener Wein- und Heurigenleben schätzen."}]'::jsonb, ''),
  ('muthgossn', 'Muthgossn', '', '', '', '', 'Muthgasse', '[{"kategorie": "allg.", "text": "bedeutende Straße im 19. Wiener Gemeindebezirk ([[Döbling]])"}, {"kategorie": "", "text": "Sie liegt im Nordwesten Wiens und ist bekannt für ihre Mischung aus Bürogebäuden, Forschungsinstituten und Wohnhäusern"}, {"kategorie": "", "text": "Die Muthgasse hat sich in den letzten Jahrzehnten zu einem wichtigen Technologie- und Wissenschaftsstandort entwickelt und beherbergt unter anderem Institute der Universität für Bodenkultur (BOKU Wien) sowie Forschungs- und Entwicklungszentren"}, {"kategorie": "", "text": "Sie erstreckt sich von der [[Heiligenstädter]] Straße entlang des [[Donaukanals]] bis in den Bereich von [[Nußdorf]]. Sie befindet sich im Herzen eines aufstrebenden Technologieviertels, das sowohl für Wissenschaft als auch für moderne Bürobauten und urbanes Wohnen bekannt ist."}]'::jsonb, ''),
  ('kuria', 'Kuria', '', '', '', '', 'Kurier', '[{"kategorie": "allg.", "text": "\"eine der führenden Tageszeitungen in Österreich, mit Sitz in Wien\""}, {"kategorie": "", "text": "Er wurde 1954 gegründet und ist heute bekannt für seine ausgewogene und gemäßigte Berichterstattung, die sich an ein breites Publikum richtet"}, {"kategorie": "", "text": "Die Zeitung gehört mehrheitlich zur Mediengruppe Österreichischer Bundesverlag (Österreichischer Kurier) und wird von mehreren Aktionären getragen. Diese Struktur ermöglicht es dem Kurier, unabhängig von staatlicher Einflussnahme zu agieren"}, {"kategorie": "", "text": "Die Zeitung spielt eine zentrale Rolle in der österreichischen Medienlandschaft und ist sowohl in Print als auch digital eine wichtige Informationsquelle."}]'::jsonb, ''),
  ('falta', 'Falta', '', '', '', '', 'Falter', '[{"kategorie": "allg.", "text": "\"bedeutende Wiener Wochenzeitung, die sich auf investigativen Journalismus, kritische Analysen und Kulturberichterstattung spezialisiert hat\""}, {"kategorie": "", "text": "Die Zeitung erscheint seit 1977 und ist vor allem für ihre linksliberale Ausrichtung und ihren Schwerpunkt auf politischen und gesellschaftlichen Themen bekannt. Der Falter hat sich im Laufe der Zeit als eines der führenden Medien für unabhängige und investigative Berichterstattung in Österreich etabliert"}, {"kategorie": "", "text": "Die Zeitung wird oft als linksliberal und progressiv eingeordnet. Häufig deckt die Zeitung Skandale in der Politik und Wirtschaft auf und hat in Österreich einen bedeutenden Einfluss auf öffentliche Debatten. Gerade in Bereichen wie Korruptionsaufdeckung und Lobbyismus spielt die Zeitung eine zentrale Rolle im österreichischen Mediensystem"}, {"kategorie": "", "text": "Armin Thurnher, der Verleger und Gründer der Zeitung, ist einer der maßgeblichen Gesellschafter des Verlages. Dank seiner Eigentümerstruktur, die vor allem aus internen Beteiligungen besteht, kann sich der Falter von politischen und wirtschaftlichen Einflüssen weitgehend unabhängig halten."}]'::jsonb, ''),
  ('kottaedschgossn', 'Kottädschgossn', '', '', '', '', 'Cottagegasse', '[{"kategorie": "allg.", "text": "\"historische Wohnstraße,  im 18. Wiener Gemeindebezirk Währing, die durch das sogenannte [[Cottageviertel]] verläuft\""}, {"kategorie": "", "text": "Dieses Viertel ist für seine gehobenen Wohnhäuser, Villen und grünen, von Bäumen gesäumten Straßen bekannt"}, {"kategorie": "", "text": "Benannt wurde sie am 30. November 1886 (durch den Gemeindeausschuss Oberdöbling) nach dem vom 1872 gegründeten Wiener Cottageverein"}, {"kategorie": "", "text": "Der Wiener Cottage Verein wurde am 14. März 1872[1] durch eine Initiative um den Architekten Heinrich Ferstel gegründet, um der steten Wiener Wohnungsnot entgegenzuwirken und ein Leben nach dem Vorbild der englischen Gartenstädte zu ermöglichen. Dazu sollten zwischen [[Gymnasiumstraße]], [[Haizingergasse]], [[Sternwartestraße]] und Cottagegasse zunächst Ein- und Zweifamilienhäuser, so genannte Cottages entstehen"}, {"kategorie": "", "text": "Heute ist die Cottagegasse ist eine der zentralen Straßen in diesem exklusiven Stadtteil, der im späten 19. Jahrhundert als gehobenes Wohngebiet für wohlhabende Bürger Wiens konzipiert wurde"}, {"kategorie": "", "text": "Das [[Cottageviertel]] wurde ab den 1870er Jahren als Gartenstadt geplant und von der Cottage Baugesellschaft entwickelt. Die Idee war, eine Wohngegend zu schaffen, die sich durch große Grundstücke und villenartige Bauten auszeichnet, die in einer naturnahen Umgebung stehen. Die Cottagegasse ist eine der prägenden Straßen dieses Viertels und spiegelt den Charme und das gehobene Wohngefühl des Cottageviertels wider."}]'::jsonb, ''),
  ('schdeanwarteschdrossn', 'Schdeanwarteschdrossn', '', '', '', '', 'Sternwartestraße', '[{"kategorie": "allg.", "text": "ruhige Straße im 18. Wiener Gemeindebezirk ([[Währing]])"}, {"kategorie": "", "text": "Sie verläuft in einer ruhigen Wohngegend und hat ihren Namen von der nahegelegenen [[Wiener]] Universitätssternwarte, die eine der wichtigsten astronomischen Einrichtungen Wiens ist"}, {"kategorie": "", "text": "Sie liegt in einem der gehobeneren Wohnviertel Wiens, umgeben von Parks ([[Sternwartepark]], [[Türkenschanzpark]]) und historischen Gebäuden, und dient als Hauptverbindungsstraße in diesem Stadtteil"}, {"kategorie": "", "text": "Entlang der Sternwartestraße befinden sich zahlreiche historische Villen und gehobene Wohnhäuser, die teils im späten 19. Jahrhundert erbaut wurden. Diese Gebäude sind oft von großen Gärten umgeben und geben dem Viertel ein elegantes, gediegenes Erscheinungsbild. Die Gegend ist geprägt von der Cottage-Architektur, die auf eine Initiative des Cottage-Vereins zurückgeht, der im 19. Jahrhundert gegründet wurde, um exklusive und ruhige Wohngegenden mit viel Grün in Wien zu fördern. Diese Architektur spiegelt den damaligen Wunsch nach luxuriösem, aber naturverbundenem Wohnen wider"}]'::jsonb, ''),
  ('schdeanwartepark', 'Schdeanwartepark', '', '', '', '', 'Sternwartepark', '[{"kategorie": "allg.", "text": "\"historischer Park im 18. Wiener Gemeindebezirk ([[Währing]]), der die [[Wiener]] Universitätssternwarte umgibt\""}, {"kategorie": "", "text": "Er ist nicht nur ein bedeutender Ort für die wissenschaftliche Forschung, sondern auch ein beliebtes Naherholungsgebiet. Der Park erstreckt sich über eine Fläche von etwa 50 Hektar und ist größtenteils für die Öffentlichkeit zugänglich, jedoch ist der Zugang zum inneren Bereich der Sternwarte eingeschränkt, da er für wissenschaftliche Zwecke genutzt wird"}, {"kategorie": "", "text": "Der Sternwartepark wurde im Zusammenhang mit dem Bau der Universitätssternwarte Wien im Jahr 1879 angelegt. Die Sternwarte, eine der größten in Europa, war ein wichtiger Schritt in der Entwicklung der Astronomie in Wien. Der Park wurde damals so gestaltet, dass er eine ruhige, lichtarme Umgebung für astronomische Beobachtungen bieten konnte, was bis heute eine seiner zentralen Funktionen ist"}, {"kategorie": "", "text": "Der Park zeichnet sich durch einen reichen Baumbestand aus, darunter mehrere alte Eichen, Ahornbäume und Linden, die teilweise mehrere Jahrhunderte alt sind. Die dichte Vegetation und die natürliche Gestaltung des Parks schaffen eine ruhige und abgeschiedene Atmosphäre."}]'::jsonb, ''),
  ('hainzingagossn', 'Hainzingagossn', '', '', '', '', 'Hainzingergasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 18. Wiener Gemeindebezirk ([[Währing]]), die durch das sogenannte [[Cottageviertel]] verläuft\""}, {"kategorie": "", "text": "Sie ist nach Ferdinand Hainzinger benannt, einem ehemaligen Bezirksvorsteher und Mitbegründer der Währinger Volksbank"}, {"kategorie": "", "text": "Das Cottage-Viertel zeichnet sich durch seine historische Architektur im Stil der Gründerzeit und des Jugendstils aus. Es war ursprünglich als \"Gartenstadt\" konzipiert und sollte wohlhabenden Wiener Bürgern ein ruhiges, naturverbundenes Leben ermöglichen"}, {"kategorie": "", "text": "Heute zählt es zu den begehrtesten Wohnlagen in Wien, und die Hainzingergasse trägt mit ihrer gehobenen Bebauung und Lage im Grünen zum exklusiven Charakter des Viertels bei."}]'::jsonb, ''),
  ('maxingschdrossn', 'Maxingschdrossn', '', '', '', '', 'Maxingstraße', '[{"kategorie": "allg.", "text": "bedeutende Straße im 13. Wiener Gemeindebezirk ([[Hietzing]])"}, {"kategorie": "", "text": "Sie verläuft in der Nähe des [[Tiergartens]] Schönbrunn und mündet im Süden in den [[Hietzinger]] Platz"}, {"kategorie": "", "text": "Die Maxingstraße liegt in einem der prestigeträchtigsten Bezirke Wiens und ist von historischen Gebäuden, Parkanlagen und Villengegenden umgeben. Die Straße bietet Zugang zu einigen der wichtigsten Sehenswürdigkeiten des 13. Bezirks, wie dem [[Schloss]] Schönbrunn, dem [[Tiergarten]] Schönbrunn (dem ältesten Zoo der Welt) und dem [[Hietzinger]] Friedhof, wo zahlreiche bedeutende Persönlichkeiten beerdigt sind"}, {"kategorie": "", "text": "Entlang der Maxingstraße befinden sich zahlreiche Jugendstilvillen und historische Wohnhäuser, die den noblen Charakter des Bezirks widerspiegeln. Die Architektur entlang der Straße ist geprägt von Villen aus der [[Gründerzeit]] und Gebäuden mit kunstvollen Fassaden."}]'::jsonb, ''),
  ('wognbuag', 'Wognbuag', '', '', '', '', 'Wagenburg', '[{"kategorie": "allg.", "text": "\"Museum im [[Schloss]] Schönbrunn in Wien, das eine bedeutende Sammlung von historischen Kutschen, Wagen, Schlitten und Sätteln der Habsburger Monarchie beherbergt\""}, {"kategorie": "", "text": "Diese Fahrzeuge waren ein zentraler Teil des kaiserlichen Lebens und wurden bei Staatsbesuchen, Zeremonien, Hochzeiten und anderen festlichen Anlässen verwendet"}, {"kategorie": "", "text": "Die Wagenburg geht auf die kaiserlichen Sammlungen der Habsburger zurück und wurde nach dem Ende der Monarchie im Jahr 1918 als Museum zugänglich gemacht. Die Ausstellung zeigt eine beeindruckende Auswahl an Fahrzeugen, die vom 18. Jahrhundert bis zum Ende der Monarchie genutzt wurden. Zu den wichtigsten Exponaten gehören prunkvolle Staatskarossen, die bei kaiserlichen Zeremonien eingesetzt wurden, sowie Leichenwagen und Reisewagen"}, {"kategorie": "", "text": "Zu den Hauptattraktionen zählen: die kaiserliche Staatskarosse (eine prunkvolle Kutsche, die bei feierlichen Anlässen wie Krönungen und Hochzeiten verwendet wurde), der Trauerwagen von Kaiser [[Franz]] Joseph I. (der Leichenwagen, der beim Staatsbegräbnis von Kaiser Franz Joseph im Jahr 1916 genutzt wurde), die Kutschen von Kaiserin Elisabeth ([[Sisi]]), die sie bei Reisen und offiziellen Anlässen benutzte, sowie mehrere Kinderschlitten und Spielkutschen (diese wurden von den kaiserlichen Kindern genutzt und geben Einblicke in das private Leben der kaiserlichen Familie)."}]'::jsonb, ''),
  ('auhofschdrossn', 'Auhofschdrossn', '', '', '', '', 'Auhofstraße', '[{"kategorie": "allg.", "text": "wichtige Straße im 13. Wiener Gemeindebezirk ([[Hietzing]]), die ihren Namen vom Stadtteil [[Auhof]] ableitet"}, {"kategorie": "", "text": "Sie beginnt am [[Hietzinger]] Platz im 13. Bezirk und verläuft westwärts durch ein ruhiges Wohngebiet, das für seine Villen und die Nähe zu großen Erholungsgebieten wie dem [[Lainzer]] Tiergarten und dem [[Wienerwald]] bekannt ist"}, {"kategorie": "", "text": "Sie endet an der [[Wientalstraße]], die eine wichtige Verbindung zur Wiener Innenstadt darstellt"}]'::jsonb, ''),
  ('wiintoi', 'Wiintoi', '', '', '', '', 'Wiental', '[{"kategorie": "allg.", "text": "\"Tal in Wien, das sich entlang des [[Wienflusses]] erstreckt\""}, {"kategorie": "", "text": "Es beginnt westlich der Stadt, im [[Wienerwald]], und zieht sich in Richtung des Stadtzentrums bis zur Mündung des Wienflusses in den [[Donaukanal]]"}, {"kategorie": "", "text": "Entlang des Wientals verläuft die Westbahn sowie die U-Bahn-Linie U4, die eine wichtige Verbindung zwischen den westlichen Vororten Wiens und dem Stadtzentrum bietet. Die Wientallinie der U4 folgt in weiten Teilen dem Verlauf des Wienflusses und verbindet wichtige Knotenpunkte wie [[Hietzing]], [[Schönbrunn]] und [[Karlsplatz]]"}, {"kategorie": "", "text": "Neben der Bahnverbindung verläuft auch die [[Wientalstraße]] durch das Tal, eine wichtige Verkehrsader, die den westlichen Teil Wiens mit dem Zentrum verbindet (\"Wiener Westeinfahrt\")."}]'::jsonb, ''),
  ('wiintoischdrossn', 'Wiintoischdrossn', '', '', '', '', 'Wientalstraße', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im Westen Wiens, die entlang des [[Wientals]] und des [[Wienflusses]] verläuft"}, {"kategorie": "", "text": "Sie dient als wichtige Verbindung zwischen dem Wiener Stadtzentrum und den westlichen Vororten sowie den angrenzenden Gebieten des Wienerwalds"}, {"kategorie": "", "text": "Die Wientalstraße beginnt im Bereich des 14. Bezirks ([[Penzing]]), nahe dem [[Auhof]] und dem [[Lainzer]] Tiergarten, und verläuft entlang des [[Wienflusses]] Richtung Osten, durch die westlichen Wiener Bezirke. Sie führt dabei durch den 13. Bezirk ([[Hietzing]]) und weiter durch die inneren Bezirke wie den 6. Bezirk ([[Mariahilf]]). Die Straße verläuft parallel zur U-Bahn-Linie U4, die ebenfalls dem Verlauf des Wienflusses folgt"}, {"kategorie": "", "text": "Die Wientalstraße spielt eine wichtige Rolle für den Verkehr zwischen dem Wiener Stadtzentrum und den westlichen Bezirken sowie den angrenzenden Vororten. Sie ist eine zentrale Achse für den Pendlerverkehr und wird vulgo auch als \"Wiener Westeinfahrt\" bezeichnet."}]'::jsonb, ''),
  ('ameisgossn', 'Ameisgossn', '', '', '', '', 'Ameisgasse', '[{"kategorie": "allg.", "text": "\"Straße im 14. Wiener Gemeindebezirk ([[Penzing]]), die durch eine ruhige Wohngegend mit einer Mischung aus älteren Gebäuden und modernen Wohnanlagen verläuft\""}, {"kategorie": "", "text": "Der Straßenname leitet sich von einem ehemaligen Gutshof namens \"Ameis\" ab, der in dieser Gegend lag und bis ins 18. Jahrhundert zurückgeht"}, {"kategorie": "", "text": "Im Laufe der Zeit verschwand der Gutshof, und das Gebiet wurde urbanisiert. Die Ameisgasse erinnert heute noch an dieses historische Gut, das in der Entwicklung des 14. Bezirks eine gewisse Bedeutung hatte. Der Name „Ameis“ findet sich auch in anderen Straßennamen und Gebäuden im Bezirk wieder und bleibt als Teil der regionalen Geschichte erhalten"}]'::jsonb, ''),
  ('ameisbochschzaeun', 'Ameisbochschzäun', '', '', '', '', 'Ameisbachzeile', '[{"kategorie": "allg.", "text": "\"Straße im 14. Wiener Gemeindebezirk ([[Penzing]]), die entlang des historischen Ameisbachs durch den Stadtteil [[Breitensee]] verläuft\""}, {"kategorie": "", "text": "Der Name der Straße erinnert an den kleinen Bach, der einst durch dieses Gebiet floss"}, {"kategorie": "", "text": "Der Ameisbach war ein kleiner Wasserlauf, der im Steinhofpark entsprang und durch den heutigen 14. Bezirk floss. Im Laufe der Urbanisierung wurde der Bach zunehmend reguliert und schließlich in den Wienfluss eingeleitet. Heute ist der Bach weitgehend unterirdisch kanalisiert, doch sein Verlauf prägt noch immer die Struktur des Bezirks"}, {"kategorie": "", "text": "Am Ameisbach entstanden einst die ersten [[Wiener]] Schrebergärten"}, {"kategorie": "", "text": "Die Ameisbachzeile ist heute vor allem eine Wohnstraße, die von Mehrfamilienhäusern, kleineren Gärten und Grünflächen umgeben ist. Sie ist Teil eines ruhigen, städtischen Wohnviertels, das sich durch seine Nähe zu Natur- und Erholungsgebieten auszeichnet."}]'::jsonb, ''),
  ('hadikgossn', 'Hadikgossn', '', '', '', '', 'Hadikgasse', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 14. Wiener Gemeindebezirk ([[Penzing]]), die als zentrale Verbindung zwischen dem Stadtzentrum und dem westlichen Stadtrand Wiens dient"}, {"kategorie": "", "text": "Die Straße ist ein bedeutender Teil der Verkehrsachse in Richtung Westen, verläuft entlang des [[Wienflusses]] und führt bis [[Auhof]], wo sie in die Westautobahn (A1) übergeht"}, {"kategorie": "", "text": "Die Straße ist nach András Hadik, einem ungarischen General und Feldmarschall in der kaiserlichen Armee des 18. Jahrhunderts, benannt. Hadik erlangte Berühmtheit durch seine militärischen Erfolge im Siebenjährigen Krieg und seine erfolgreiche Eroberung Berlins im Jahr 1757"}, {"kategorie": "", "text": "Mit ihrer Lage in einem vielfältigen Stadtteil, der sowohl Wohn- als auch Erholungsgebiete bietet, ist die Hadikgasse ein wichtiger Bestandteil der städtischen Infrastruktur Wiens"}]'::jsonb, ''),
  ('hadikpark', 'Hadikpark', '', '', '', '', 'Hadikpark', '[{"kategorie": "allg.", "text": "\"kleine, aber bedeutende Grünanlage im 14. Wiener Gemeindebezirk ([[Penzing]]), die an der Hadikgasse liegt\""}, {"kategorie": "", "text": "Der Park liegt an der [[Hadikgasse]] in einer stark frequentierten Umgebung und dient als grüner Rückzugsort für Anwohner und Passanten, die im hektischen Stadtverkehr eine Erholungsmöglichkeit suchen"}, {"kategorie": "hist.", "text": "Das 1822 angelegte Parkgelände längs des [[Wienflusses]] gelangte 1838, nach dem Tod des Herrschaftsinhabers und Industriellen Franz Xaver Freiherr von Mayr, testamentarisch an die Gemeinde Penzing. 1853 errichtete die Gemeinde dem Stifter ein Denkmal mit vier Inschrifttafeln und einer weiblichen Gusseisenfigur mit aufgeschlagenem Buch"}, {"kategorie": "", "text": "Der Park ist nach András Hadik, einem ungarischen General und Feldmarschall in der kaiserlichen Armee des 18. Jahrhunderts, benannt. Hadik erlangte Berühmtheit durch seine militärischen Erfolge im Siebenjährigen Krieg und seine erfolgreiche Eroberung Berlins im Jahr 1757."}]'::jsonb, ''),
  ('dehnepark', 'Dehnepark', '', '', '', '', 'Dehnepark', '[{"kategorie": "allg.", "text": "\"naturparkartige Parkanlage im 14. Wiener Gemeindebezirk ([[Penzing]]) mit einer Fläche von rund 50.000 m²\""}, {"kategorie": "", "text": "Der Park ist ein Teil des [[Wienerwalds]] und gilt aufgrund seines Altbaumbestandes und seines Lebensraumes als einzigartig. Er liegt im [[Rosental]] am Osthang des Hausberges von [[Hütteldorf]], dem [[Satzberg]], und auf der Gegenseite an den Hängen der [[Steinhofgründe]]"}, {"kategorie": "", "text": "Das Zentrum des Dehneparks bilden der künstlich aufgestaute Dehneteich und die darunter liegende große Wiese, die durch rezente Einwölbung des Rosenbaches vergrößert wurde"}, {"kategorie": "", "text": "Der Dehnepark wurde ursprünglich als Landschaftsgarten für die Fürstin Maria Antoine Paar (geb. Liechtenstein) errichtet. Er wurde in den Jahren 1791 bis 1804 von Friedrich Mayern entworfen und ursprünglich im Stil eines englischen Landschaftsgartens errichtet. Durch verschiedene Bauten – wie Tempelchen, Pavillons, Grotten – und Gebäude bekam der Park ein biedermeierlich romantisches Gepräge. Diese Elemente der Gartengestaltung verschwanden allerdings im 19. und 20. Jahrhundert zum Großteil wieder, bis auf die neugotische Ruinenvilla aus dem späten 18. Jahrhundert"}, {"kategorie": "", "text": "Seinen Namen bekam der Park von dem Zuckerbäcker August Dehne. Dieser verdiente im 19. Jahrhundert mit seiner Konditorei am [[Michaelerplatz]] (später Konditorei Demel am Kohlmarkt) sehr gut, so dass er den Ertrag in das große, bewaldete Grundstück bei [[Hütteldorf]] investierte"}, {"kategorie": "", "text": "Jahrzehnte später kaufte der Wiener Filmregisseur Willi Forst dieses Gelände und errichtete dort eine Villa. Nach dem Zweiten Weltkrieg zeigte die Gemeinde Wien Interesse am langsam verwildernden Park, erwarb diesen 1969 käuflich von Forst und machte ihn ab 1973 der Öffentlichkeit zugänglich. Seither steht der Dehnepark in der Verwaltung und Betreuung des Forstamts der Stadt Wien (Magistratsabteilung 49)."}]'::jsonb, ''),
  ('cumberlandschdrossn', 'Cumberlandschdrossn', '', '', '', '', 'Cumberlandstraße', '[{"kategorie": "allg.", "text": "\"Wohnstraße im 14. Wiener Gemeindebezirk ([[Penzing]]), die durch eine ruhige Wohngegend verläuft\""}, {"kategorie": "", "text": "Die Straße ist nach den Herzögen von Cumberland benannt, einem Zweig der britischen Königsfamilie. Im 19. Jahrhundert musste der Herzog von Cumberland, Ernst August, nach Österreich ins Exil gehen, nachdem er den Titel des Königs von Hannover verloren hatte. In Wien und Umgebung ließ sich die Familie nieder, was zur Benennung mehrerer Straßen und Gebäude in Bezug auf diese historischen Persönlichkeiten führte"}, {"kategorie": "", "text": "Die Cumberlandstraße liegt in einem eher ruhigen Teil des 14. Bezirks, umgeben von Wohnhäusern und Schulen. In ihrer Umgebung gibt es kleinere Geschäfte, Dienstleistungsbetriebe und öffentliche Verkehrsmittel, die die Anbindung an den Rest der Stadt gewährleisten"}, {"kategorie": "", "text": "Trotz ihrer zentralen Lage in Penzing behält die Straße einen ruhigen, fast dörflichen Charakter bei."}]'::jsonb, ''),
  ('maroitingaschdrossn', 'Maroitingaschdrossn', '', '', '', '', 'Maroltingerstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Verkehrsstraße, die den Stadtteil [[Breitensee]] im 14. Bezirk ([[Penzing]]) mit dem westlichen [[Ottakring]] (16. Wiener Gemeindebezirk) verbindet\""}, {"kategorie": "", "text": "Sie verläuft durch ein urbanes Wohn- und Geschäftsviertel und spielt eine wichtige Rolle im lokalen Verkehrssystem"}, {"kategorie": "", "text": "Die Straße ist nach der Familie Maroltinger benannt, konkret nach nach den Wiener Bürgern Michael und Andreas Maroltinger, die den niederösterreichischen Landständen angehörten und Anfang des 16. Jahrhunderts in der Region ansässig waren"}, {"kategorie": "", "text": "Der Name der Straße erinnert an die ländliche Vergangenheit des Bezirks, als Ottakring noch ein Dorf am Stadtrand von Wien war. Mit der fortschreitenden Urbanisierung im 19. und 20. Jahrhundert wurde Ottakring in das Stadtgebiet eingegliedert, und die Maroltingerstraße entwickelte sich zu einer wichtigen Verkehrsverbindung im Bezirk."}]'::jsonb, ''),
  ('montleaaschdrossn', 'Montleaaschdrossn', '', '', '', '', 'Montleartstraße', '[{"kategorie": "allg.", "text": "bedeutende Stadtrandstraße im westlichen Wien, die vom 16. Bezirk ([[Ottakring]]) bis in den 14. Bezirk ([[Penzing]]), genauer gesagt in den Stadtteil [[Breitensee]], führt"}, {"kategorie": "", "text": "Die Straße wurde nach Maria Theresia Gräfin von Montleart benannt, die im 19. Jahrhundert in Wien lebte. Die Gräfin war eine bekannte Adlige und Gutsbesitzerin, deren Name bis heute in Wien präsent ist. Der Einfluss der Aristokratie, besonders im Bezirk Penzing, spiegelt sich in mehreren Straßenbenennungen wider, die an Adelsfamilien und Persönlichkeiten aus der österreichischen Geschichte erinnern"}, {"kategorie": "", "text": "Die Montleartstraße ist Teil eines dicht bebauten Stadtgebiets und wird von Wohnhäusern, kleineren Geschäften und öffentlichen Einrichtungen gesäumt"}, {"kategorie": "", "text": "Die Straße liegt zudem auch in der Nähe wichtiger städtischer Infrastrukturen, wie dem [[Bahnhof]] Breitensee und mehreren Straßenbahn- und Buslinien, die den öffentlichen Verkehr in diesem Teil Wiens bedienen. Diese Verbindung macht die Montleartstraße zu einer wichtigen lokalen Verkehrsader zwischen den Bezirken Ottakring und Penzing."}]'::jsonb, ''),
  ('wuehoeminangossn', 'Wühöminangossn', '', '', '', '', 'Wilhelminengasse', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße im 16. Wiener Gemeindebezirk ([[Ottakring]])"}, {"kategorie": "", "text": "Sie verläuft im nördlichen Teil des Bezirks und verbindet das städtische Gebiet mit den Hängen des [[Wilhelminenbergs]], einem der höher gelegenen Erholungsgebiete Wiens"}, {"kategorie": "", "text": "Die Wilhelminenstraße ist nach dem [[Wilhelminenberg]] benannt, einem historischen Gebiet im 16. Bezirk, das sich im 19. Jahrhundert zu einem beliebten Ausflugsziel entwickelte. Der Name geht auf Wilhelmine, eine Tochter von Herzog Albrecht, zurück"}, {"kategorie": "", "text": "Der Wilhelminenberg selbst und die umliegenden Anlagen wurden im 19. und 20. Jahrhundert stetig erweitert und in die Stadt integriert"}, {"kategorie": "", "text": "Die Straße ist eine zentrale Verkehrsader und verbindet den urbanen Teil Ottakrings mit den Wohngebieten und Erholungsflächen in den höher gelegenen Westteilen des Bezirks, die an den Hängen des [[Wienerwalds]] liegen."}]'::jsonb, ''),
  ('wattgossn', 'Wattgossn', '', '', '', '', 'Wattgasse', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße, die sich durch den 16. Wiener Gemeindebezirk ([[Ottakring]]) und den 17. Wiener Gemeindebezirk ([[Hernals]]) erstreckt"}, {"kategorie": "", "text": "Sie ist benannt nach dem englischen Erfinder der Niederdruck-Dampfmaschine, James Watt (* 19. Jänner 1736 Greenock-on-Clyde, † 19. August 1819 Heathfield bei Birmingham)"}, {"kategorie": "", "text": "Die Wattgasse ist eine belebte Verkehrsstraße, die durch dicht besiedelte Gebiete führt und größere Verkehrsadern wie die [[Hernalser]] Hauptstraße mit anderen Hauptverkehrswegen verbindet"}, {"kategorie": "", "text": "Entlang der Straße gibt es zahlreiche Wohnhäuser, Einkaufs-, Amts- und Bildungseinrichtungen."}]'::jsonb, ''),
  ('foeoebaschdrossn', 'Fööbaschdrossn', '', '', '', '', 'Felberstraße', '[{"kategorie": "allg.", "text": "wichtige Verkehrsstraße im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]])"}, {"kategorie": "", "text": "Sie verläuft parallel zur Westbahnstrecke und dient als eine der Hauptverbindungsstraßen im Bezirk, vor allem in Richtung des [[Westbahnhofs]] und des [[Gürtels]]"}, {"kategorie": "", "text": "Sie ist benannt nach der Ried \"Felbern\", wobei \"Felber\" die ursprüngliche Bezeichnung für \"Weidenbaum\" ist"}, {"kategorie": "", "text": "Die Felberstraße wird von einer Mischung aus Wohngebäuden, Geschäften und Büros gesäumt. In unmittelbarer Nähe befinden sich auch größere Einkaufszentren wie die [[Lugner]] City und die [[BahnhofCity]] West am Westbahnhof."}]'::jsonb, ''),
  ('gablenzgossn', 'Gablenzgossn', '', '', '', '', 'Gablenzgasse', '[{"kategorie": "allg.", "text": "bedeutende Verkehrsstraße, die sich vom 16. Wiener Gemeindebezirk ([[Ottakring]]) bis zum 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]) erstreckt"}, {"kategorie": "", "text": "Sie ist nach Ludwig Freiherr von Gablenz benannt, einem in Jena geborenen österreichischen General der Kavallerie (1814-1874), der 1866 im Deutschen Krieg als Kommandant des X. österreichischen Armee-Korps die preußische Armee besiegte und auch in der Schlacht bei Königgrätz am 3. Juli 1866 kämpfte"}, {"kategorie": "", "text": "Die Gablenzgasse beginnt im 16. Bezirk und zieht sich in Richtung [[Gürtel]] im 15. Bezirk"}, {"kategorie": "", "text": "Sie verbindet Wohn- und Geschäftsviertel miteinander und ist gesäumt von einer Mischung aus Wohnhäusern, Geschäften, Restaurants und öffentlichen Einrichtungen"}, {"kategorie": "", "text": "Aufgrund ihrer zentralen Lage ist die Gablenzgasse eine vielbefahrene Straße und wird sowohl von Pendlern als auch von Anwohnern intensiv genutzt."}]'::jsonb, ''),
  ('maeazschdrossn', 'Mäazschdrossn', '', '', '', '', 'Märzstraße', '[{"kategorie": "allg.", "text": "\"wichtige Verkehrsstraße im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]), die beim Gürtel beginnt und parallel zur Hütteldorfer Straße und der Felberstraße durch ein dicht besiedeltes Wohn- und Geschäftsviertel des Bezirks verläuft\""}, {"kategorie": "", "text": "Die Benennung der Straße erfolgte im Gedenken an die Gefallenen der Märzrevolution (13.-16. März 1848). Die Märzgefallenen wurden auf dem Schmelzer Kommunalfriedhof (ab 1874 nicht mehr belegt) beerdigt und erhielten 1864 ein Mahnmal (Denkmal für die Opfer der Märzrevolution 1848). An der Stelle des ehemaligen Schmelzer Friedhofs befinden sich heute der Märzpark beziehungsweise die Stadthalle"}, {"kategorie": "", "text": "In der Nähe der Märzstraße befinden sich mehrere Bildungs- und Freizeiteinrichtungen. Durch die Nähe zur [[Wiener]] Stadthalle und zur [[Lugner]] City bietet die Gegend viele Einkaufsmöglichkeiten sowie Kultur- und Freizeitangebote. Auch Wohnhäuser und lokale Geschäfte prägen das Stadtbild entlang der Märzstraße, was sie zu einer belebten und vielfältigen Umgebung macht."}]'::jsonb, ''),
  ('heabstschdrossn', 'Heabstschdrossn', '', '', '', '', 'Herbststraße', '[{"kategorie": "allg.", "text": "Straße im 16. Wiener Gemeindebezirk ([[Ottakring]]), konkret im Stadtteil [[Neulerchenfeld]]"}, {"kategorie": "", "text": "Die Herbststraße ist benannt nach Eduard Herbst, einem Wiener Rechtsgelehrten und Politiker (1820-1892)"}, {"kategorie": "", "text": "Sie verläuft durch ein dicht besiedeltes Wohngebiet und spielt eine wichtige Rolle als lokale Verkehrs- und Geschäftsstraße. Ottakring ist bekannt für seine Mischung aus traditionellen Wiener Arbeitervierteln, aufstrebenden Szenevierteln und multikultureller Vielfalt, was sich auch in der Umgebung der Herbststraße widerspiegelt"}, {"kategorie": "", "text": "An der Herbststraße befindet sich auch die renommierte \"Modeschule Herbststraße\", die eine praxisnahe Ausbildung im Bereich Mode und Design anbietet. Sie ist eine der wichtigsten Modeschulen Wiens und zieht kreative Talente aus der ganzen Stadt an."}]'::jsonb, ''),
  ('possingagossn', 'Possingagossn', '', '', '', '', 'Possingergasse', '[{"kategorie": "allg.", "text": "zentrale Verbindungsstraße im 16. Wiener Gemeindebezirk ([[Ottakring]]), die durch ein gemischtes Viertel mit Wohnhäusern und Gewerbebetrieben führt"}, {"kategorie": "", "text": "Sie ist nach Ludwig Freiherr von Possinger von Choborsky (1823-99) benannt, dem damaligen Statthalter von Niederösterreich"}, {"kategorie": "", "text": "In unmittelbarer Nähe befindet sich die [[Ottakringer]] Brauerei, eine der bekanntesten Brauereien Wiens, die dem Bezirk einen besonderen Stellenwert in der österreichischen Bierkultur verleiht. Zudem ist die Gasse von ihrer historischen Bebauung und dem typischen Wiener Stadtbild geprägt, das durch enge Straßen, hohe Wohnhäuser und belebte Plätze charakterisiert ist."}]'::jsonb, ''),
  ('oewaseeschdrossn', 'Öwaseeschdrossn', '', '', '', '', 'Oeverseestraße', '[{"kategorie": "allg.", "text": "Wohnstraße im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]])"}, {"kategorie": "", "text": "Die Straße ist benannt nach dem Gefecht bei Oeversee im Dänischen Krieg (6. Februar 1864), das unter Leitung des Freiherren von Gablenz siegreich ausgetragen wurde"}, {"kategorie": "", "text": "Die Oeverseestraße verläuft entlang der [[Schmelz]], einem großen Freizeit- und Erholungsgebiet, und führt westwärts nach [[Ottakring]]"}, {"kategorie": "", "text": "Sie verbindet mehrere wichtige Verkehrsadern und wird überwiegend von Wohnhäusern, Schulen und kleineren Geschäften gesäumt"}, {"kategorie": "", "text": "Die Straße ist von einer Mischung aus Altbauten und modernen Wohnanlagen umgeben und bietet den Bewohnern eine ruhige Wohnlage mit guter Anbindung an den öffentlichen Verkehr."}]'::jsonb, ''),
  ('schlesingaplotz', 'Schlesingaplotz', '', '', '', '', 'Schlesingerplatz', '[{"kategorie": "allg.", "text": "kleiner, repräsentativer Platz im 8. Wiener Gemeindebezirk ([[Josefstadt]]), gelegen an der [[Florianigasse]]"}, {"kategorie": "", "text": "Der Platz war ursprünglich nach dem österreichischen Geodät, Naturphilosoph und Politiker \"Joseph Schlesinger\" (1831–1901) benannt"}, {"kategorie": "", "text": "Im Auftrag der Stadt Wien hat eine HistorikerInnen-Kommission die historische Bedeutung jener Persönlichkeiten, nach denen Wiener Straßen benannt sind, von 2011 bis 2013 untersucht sowie eine zeithistorische Kontextualisierung vorgenommen. Josef Schlesingers Reden im Reichsrat sowie seine Schriften (z. B. \"Volksgeld“) waren von antisemitischer Polemik durchsetzt, beispielsweise wenn er gegen das \"jüdisch dominierte Großkapital“ agitierte"}, {"kategorie": "", "text": "Demzufolge erging ein Gemeinderatsbeschluss, wonach der Platz nunmehr offiziell nach der österreichischen Frauenrechtlerin und Politikerin der Sozialdemokratischen Arbeiterpartei \"Therese Schlesinger\" (1863-1940) benannt ist"}, {"kategorie": "", "text": "Der Schlesingerplatz liegt im Herzen der [[Josefstadt]]. In seiner Umgebung gibt es viele historische Wohngebäude, die den Charme des 8. Bezirks ausmachen, sowie einige Cafés und kleine Geschäfte."}]'::jsonb, ''),
  ('bennoplotz', 'Bennoplotz', '', '', '', '', 'Bennoplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 8. Wiener Gemeindebezirk ([[Josefstadt]]), konkret im Stadtteil [[Breitenfeld]]\""}, {"kategorie": "", "text": "Er liegt in der Nähe der [[Josefstädter]] Straße und ist nach Benno Pointner, einem Abt des Schottenstifts in Wien benannt (* 22. September 1722 in Rafing; † 15. Februar 1807 in Wien)"}, {"kategorie": "", "text": "Der Platz ist von einer Mischung aus Wohnhäusern, Geschäften, und öffentlichen Einrichtungen umgeben und dient als lokaler Treffpunkt und Ruheort für die Bewohner des Bezirks."}]'::jsonb, ''),
  ('koppschdrossn', 'Koppschdrossn', '', '', '', '', 'Koppstraße', '[{"kategorie": "allg.", "text": "\"zentrale Verkehrsstraße im 16. Wiener Gemeindebezirk ([[Ottakring]])\""}, {"kategorie": "", "text": "Sie verläuft durch ein dicht besiedeltes städtisches Gebiet und verbindet wichtige Verkehrspunkte und Wohngebiete miteinander"}, {"kategorie": "", "text": "Die Straße wurde nach dem österreichischen Rechtsanwalt und Reichsratsabgeordneten Dr. Josef Kopp (* 13. April 1827 Wien, † 22. Jänner 1907 Wien) benannt, der als Student während der Revolution 1848 in der Akademischen Legion kämpfte"}, {"kategorie": "", "text": "Die Koppstraße liegt in einem urbanen, multikulturellen Viertel, das vor allem durch Altbauten geprägt ist. Sie ist eine stark frequentierte Straße, die den Verkehr im westlichen Teil Ottakrings maßgeblich beeinflusst."}]'::jsonb, ''),
  ('siibnschdeangossn', 'Siibnschdeangossn', '', '', '', '', 'Siebensterngasse', '[{"kategorie": "allg.", "text": "\"bekannte Straße im 7. Wiener Gemeindebezirk ([[Neubau]]), einem der zentralen und trendigen Bezirke Wiens\""}, {"kategorie": "", "text": "Sie ist eine der ältesten Straßen des Bezirks und verläuft in einem Gebiet, das für seine kulturelle Vielfalt, Kunstszene und eine Mischung aus historischen und modernen Gebäuden bekannt ist"}, {"kategorie": "", "text": "Die Straße ist nach dem Hausschild \"Zu den sieben Sternen\" (Nummer 13) benannt. Hausschilder bildeten in der Stadt und in den Vorstädten bis zur Einführung der Konskriptionsnummern unter Maria Theresia (1771; Häusernummerierung) die einzige Möglichkeit zur Kennzeichnung von Häusern"}, {"kategorie": "", "text": "Historisch war die Siebensterngasse ein Zentrum für Handwerker, insbesondere für Schneider und Gerber, die hier im 18. und 19. Jahrhundert ansässig waren"}, {"kategorie": "", "text": "Heute hat sich die Siebensterngasse zu einer beliebten Straße mit Boutiquen, Cafés, Restaurants und Kunstgalerien entwickelt. Sie ist ein zentraler Teil des kreativen Bezirks Neubau und zieht Künstler, Designer und junge Leute an, die die Mischung aus historischem Charme und modernem Flair schätzen."}]'::jsonb, ''),
  ('schottnfoeoedgossn', 'Schottnföödgossn', '', '', '', '', 'Schottenfeldgasse', '[{"kategorie": "allg.", "text": "Straße im 7. Wiener Gemeindebezirk ([[Neubau]]), die sich durch eine zentrale Lage und ihre historische Bedeutung auszeichnet"}, {"kategorie": "", "text": "Die Schottenfeldgasse beginnt im Süden an der [[Lerchenfelder]] Straße und verläuft in nordwestlicher Richtung, bis sie an der [[Mariahilfer]] Straße endet. Die Straße durchquert den westlichen Teil des 7. Bezirks und liegt in einem stark urbanisierten Gebiet, das von Wohnhäusern, Geschäften und Büros geprägt ist"}, {"kategorie": "", "text": "Die Schottenfeldgasse liegt in einem Viertel, das im 18. und 19. Jahrhundert als Schottenfeld bekannt war. Dieser Stadtteil war ursprünglich ein Handwerkerviertel, das sich rasch entwickelte, als Wien wuchs"}, {"kategorie": "", "text": "Die einst einzige Verbindung von der Mariahilfer zur Lerchenfelder Straße war im 18. Jahrhundert nur im südlichen Teil verbaut, die restliche Verbauung (auf dem Gebiet des ehemaligen Schottenfelds) folgte nach und nach bis 1848."}]'::jsonb, ''),
  ('ziiglagossn', 'Ziiglagossn', '', '', '', '', 'Zieglergasse', '[{"kategorie": "allg.", "text": "\"Straße im 7. Wiener Gemeindebezirk ([[Neubau]]), einem belebten und zentral gelegenen Stadtteil Wiens\""}, {"kategorie": "", "text": "Sie ist für ihre Lage in einem der kreativsten und trendigsten Bezirke der Stadt bekannt und verbindet Wohnviertel mit Geschäftsstraßen und kulturellen Einrichtungen"}, {"kategorie": "", "text": "Die Straße ist benannt nach den hier noch am Beginn des 19. Jahrunderts anzutreffenden Ziegeleien"}, {"kategorie": "", "text": "Im 19. Jahrhundert entwickelte sich der Bezirk [[Neubau]] zu einem wichtigen städtischen Wohn- und Geschäftsviertel, und die Zieglergasse spielte eine bedeutende Rolle in dieser Entwicklung"}, {"kategorie": "", "text": "Die Zieglergasse ist von einer Mischung aus Altbauten, modernen Wohnhäusern, Geschäften, Büros und Restaurants geprägt. Besonders die Nähe zur [[Mariahilfer]] Straße macht sie zu einem beliebten Ort zum Wohnen und Arbeiten."}]'::jsonb, ''),
  ('satzbeag', 'Satzbeag', '', '', '', '', 'Satzberg', '[{"kategorie": "allg.", "text": "\"bewaldeter Hügel im 14. Wiener Gemeindebezirk ([[Penzing]]), der zum [[Wienerwald]] gehört\""}, {"kategorie": "", "text": "Der Satzberg liegt auf einer Höhe von etwa 435 Metern und ist Teil jener Hügelkette, die den westlichen Stadtrand Wiens prägt und eine ruhige Erholungszone abseits des städtischen Trubels bietet"}, {"kategorie": "", "text": "Der Satzberg befindet sich im Stadtteil [[Hadersdorf-Weidlingau]] und liegt in der Nähe von [[Hütteldorf]] und dem [[Dehnepark]]. Er ist gut erreichbar und wird von Wanderwegen durchzogen, die Besucher durch Wälder und Wiesen führen. In der Umgebung des Satzbergs befinden sich auch einige landwirtschaftlich genutzte Flächen."}]'::jsonb, ''),
  ('schofbeag', 'Schofbeag', '', '', '', '', 'Schafberg', '[{"kategorie": "allg.", "text": "\"bewaldeter Hügel im 17. Wiener Gemeindebezirk ([[Hernals]]) sowie teilweise im 18. Bezirk ([[Währing]])\""}, {"kategorie": "", "text": "Er gehört zu den Ausläufern des [[Wienerwaldes]] und liegt auf etwa 390 Metern über dem Meeresspiegel"}, {"kategorie": "", "text": "Der Schafberg liegt an der Grenze zwischen den Bezirken Hernals und Währing im Nordwesten Wiens und bildet die Grenze zwischen den Stadtteilen [[Pötzleinsdorf]] und [[Neuwaldegg]]"}, {"kategorie": "", "text": "Die oberen Waldpartien mit der Ladenburghöhe sind von markierten Parkwegen durchzogen. Auf der Höhe befindet sich ein Restaurant"}, {"kategorie": "", "text": "Der Schafberg ist Teil des Grüngürtels von Wien, wird urkundlich erstmals 1366 genannt (\"gelegen an dem underm Schofberg\") und hat seinen Namen von dem dort einst befindlichen Schafweideplatz"}, {"kategorie": "", "text": "Es handelt sich um den südlichen der zwei parallel verlaufenden langgestreckten Höhenrücken des 18. Bezirks, die von Nordwesten nach Südosten liegen. Der Schafberg geht in den Mitterberg, dann in den Ganslberg über und findet sein Ende erst bei der heutigen [[Gürtelstraße]], wo der Steilrand deutlich zu erkennen ist"}]'::jsonb, ''),
  ('schofbeaggossn', 'Schofbeaggossn', '', '', '', '', 'Schafberggasse', '[{"kategorie": "allg.", "text": "\"ruhige Straße im 18. Wiener Gemeindebezirk ([[Währing]]), die durch ein grünes Wohngebiet verläuft\""}, {"kategorie": "", "text": "Sie liegt am Rande des [[Schafbergs]], einem beliebten Naherholungsgebiet in Wien, und ist eine der Straßen, die den gleichnamigen Hügel und seine Umgebung erschließen"}, {"kategorie": "", "text": "Die Schafberggasse beginnt bei der [[Pötzleinsdorfer]] Straße und verläuft durch ein gepflegtes Wohnviertel, das vor allem von Einfamilienhäusern und Villen geprägt ist. Die Straße zieht sich entlang der Hänge des Schafbergs und bietet eine ruhige Wohnlage in unmittelbarer Nähe zur Natur"}]'::jsonb, ''),
  ('schofbeagbood', 'Schofbeagbood', '', '', '', '', 'Schafbergbad', '[{"kategorie": "allg.", "text": "\"beliebtes Freibad im 18. Wiener Gemeindebezirk ([[Währing]]), am Rand des [[Schafbergs]] gelegen\""}, {"kategorie": "", "text": "Es entstand 1974 als städtisches Sommerbad anstelle eines älteren Privatbades und bietet großzügige Liegewiesen, Spielplätze und verschiedene Sportanlagen, darunter Beachvolleyballplätze und Tischtennis"}, {"kategorie": "", "text": "Durch die Lage am Schafberg, einem der höher gelegenen Gebiete Wiens, bietet das Bad einen hervorragenden Blick über die Stadt, was es zu einem besonders attraktiven Ziel für Familien, Sonnenanbeter und Erholungssuchende macht. Die Anfahrt ist mit öffentlichen Verkehrsmitteln oder dem Auto gut möglich."}]'::jsonb, ''),
  ('kropfnwoidlbood', 'Kropfnwoidlbood', '', '', '', '', 'Krapfenwaldlbad', '[{"kategorie": "allg.", "text": "\"traditionsreiches Freibad im 19. Wiener Gemeindebezirk ([[Döbling]]), das am Rande des [[Wienerwaldes]] liegt\""}, {"kategorie": "", "text": "Es befindet sich in einer idyllischen, erhöhten Lage und bietet den Badegästen nicht nur Badespaß, sondern auch einen spektakulären Panoramablick auf die Stadt Wien"}, {"kategorie": "", "text": "Das Krapfenwaldlbad wurde im Jahr 1923 eröffnet und gehört zu den ältesten Freibädern Wiens. Es war ursprünglich als Erholungsort für die Wiener Bevölkerung gedacht und hat sich bis heute seinen Charme und seine Naturverbundenheit bewahrt"}, {"kategorie": "", "text": "Der Name „Krapfenwaldl“ leitet sich von Franz Josef von Krapf († 1732) ab, einem einstigen Großgundbesitzer dieser bewaldeten Gegend (\"Krapfenwaldl\")"}, {"kategorie": "", "text": "Das Bad wurde am 29. Mai 1952 nach einer Erweiterung neu eröffnet (Fassungsvermögen 4.500 Personen, Gesamtfläche 44.000 m²)."}]'::jsonb, ''),
  ('kropfnwoidgossn', 'Kropfnwoidgossn', '', '', '', '', 'Krapfenwaldgasse', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 19. Wiener Gemeindebezirk ([[Döbling]]), die sich in einer der nobelsten Wohngegenden Wiens befindet\""}, {"kategorie": "", "text": "Sie verläuft am Rande des Wienerwaldes und liegt in unmittelbarer Nähe zum [[Krapfenwaldlbad]], einem beliebten Freibad in der Region"}, {"kategorie": "", "text": "Der Name „Krapfenwaldl“ leitet sich von Franz Josef von Krapf († 1732) ab, einem einstigen Großgundbesitzer dieser bewaldeten Gegend (\"Krapfenwaldl\")"}, {"kategorie": "", "text": "Die Gasse führt durch das [[Grinzinger]] Villenviertel und ist von exklusiven Wohnhäusern und Villen umgeben, die die gehobene Wohnkultur dieses Stadtteils widerspiegeln."}]'::jsonb, ''),
  ('gusshausschdrossn', 'Gusshausschdrossn', '', '', '', '', 'Gußhausstraße', '[{"kategorie": "allg.", "text": "zentrale Straße im 4. Wiener Gemeindebezirk ([[Wieden]]), die in der Nähe bedeutender Bildungs- und Forschungseinrichtungen (siehe [[TU Wien]]) sowie zahlreicher historischer Gebäude liegt (siehe [[Karlskirche]])"}, {"kategorie": "", "text": "Die Gusshausstraße erstreckt sich vom [[Schwarzenbergplatz]] im Norden bis zur [[Favoritenstraße]] im Süden und liegt in einem belebten Teil des Bezirks Wieden"}, {"kategorie": "", "text": "Die Gusshausstraße liegt in einem Teil Wiens, der stark von der Barockarchitektur und der Entwicklung Wiens als kaiserliche Residenzstadt geprägt ist"}, {"kategorie": "", "text": "Benannt ist die Straße nach dem \"k. k. Gußhaus\", einer dort einst befindlichen Kunsterzgießerei."}]'::jsonb, ''),
  ('taubstummangossn', 'Taubstummangossn', '', '', '', '', 'Taubstummengasse', '[{"kategorie": "allg.", "text": "\"kurze Straße im 4. Wiener Gemeindebezirk ([[Wieden]]), die sich von der [[Favoritenstraße]] bis zur [[Argentinierstraße]] erstreckt\""}, {"kategorie": "", "text": "Die Taubstummengasse erhielt ihren Namen im 19. Jahrhundert von der nahe gelegenen Taubstummenanstalt, einer Schule für gehörlose Kinder, die dort im 18. Jahrhundert gegründet wurde"}, {"kategorie": "", "text": "Die Straße ist heute von repräsentativen Wohn- und Bürogebäuden umgeben und gehört zu den ruhigeren Straßen im 4. Bezirk"}, {"kategorie": "", "text": "Sie ist zentral gelegen, bietet eine gute Anbindung durch die U-Bahn und ist von wichtigen Wiener Institutionen umgeben"}]'::jsonb, ''),
  ('argentiniaschdrossn', 'Argentiniaschdrossn', '', '', '', '', 'Argentinierstraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 4. Wiener Gemeindebezirk ([[Wieden]])\""}, {"kategorie": "", "text": "Sie verläuft von der [[Operngasse]] in der Nähe des [[Karlsplatzes]] bis hinauf zur [[Gürtelstraße]] in der Nähe der [[Prinz-Eugen-Straße]], nahe dem [[Schloss]] Belvedere"}, {"kategorie": "", "text": "Die Straße wurde 1921 zur Erinnerung an die Hilfe Argentiniens (fünf Millionen-Spende) nach dem Ersten Weltkrieg benannt"}, {"kategorie": "", "text": "Sie verläuft durch ein urbanes und kulturell reiches Gebiet von Wieden, das für seine Architektur und seine Nähe zu vielen Wiener Sehenswürdigkeiten bekannt ist."}]'::jsonb, ''),
  ('boesnduafaschdrossn', 'Bösnduafaschdrossn', '', '', '', '', 'Bösendorferstraße', '[{"kategorie": "allg.", "text": "\"zentrale Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt),  Sie befindet sich in unmittelbarer Nähe zur [[Wiener]] Staatsoper, einem der bedeutendsten Opernhäuser der Welt\""}, {"kategorie": "", "text": "Im Mittelalter gehörte diese Gegend zur \"Vorstadt vor dem [[Kärntner]] Tor\""}, {"kategorie": "", "text": "Die Straße ist nach dem berühmten Wiener Klavierbauer Ignaz Bösendorfer benannt, dessen Firma bis heute als einer der renommiertesten Hersteller von Konzertflügeln weltweit gilt"}, {"kategorie": "", "text": "Die Bösendorferstraße liegt in einem kulturell und historisch bedeutenden Teil von Wien, mit vielen renommierten Einrichtungen in ihrer unmittelbaren Umgebung."}]'::jsonb, ''),
  ('elisabethschdrossn', 'Elisabethschdrossn', '', '', '', '', 'Elisabethstraße', '[{"kategorie": "allg.", "text": "\"zentrale Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die eine wichtige Verbindungsstraße im historischen Zentrum Wiens darstellt\""}, {"kategorie": "", "text": "Sie wurde nach Elisabeth von Österreich-Ungarn, besser bekannt als Kaiserin [[Sisi]], benannt"}, {"kategorie": "", "text": "Die Straße verläuft parallel zum [[Ring]] in unmittelbarer Nähe zu historisch bedeutenden Gebäuden sowie kulturellen Einrichtungen"}, {"kategorie": "", "text": "Im Mittelalter war die Straße noch die Grenze zu den Vorstädten vor dem [[Kärntner]] und [[Widmer]] Tor; danach war sie Teil des [[Glacis]] und damit eine unverbaute Fläche vor den Stadtmauern. Hier begann die „Katerlucke“ (auch: Kothlucke), eine kleine Ansiedelung, die entlang der heutigen [[Rahlgasse]], heute 6. Bezirk, verlief"}, {"kategorie": "", "text": "Die 1861 angelegte Elisabethstraße verläuft heute parallel zum [[Opernring]], sie beginnt bei der [[Operngasse]] und endet bei der [[Babenbergerstraße]]"}, {"kategorie": "", "text": "Die Elisabethstraße verläuft quer über den ehemaligen Koloman-Friedhof. Dieser wurde im 13. Jahrhundert rund um das Bürgerspital angelegt, bestattet wurden hier die Armen und die Pest-Toten. Der Friedhof wurde durch die Türken 1529 zerstört und letztendlich 1548 komplett eingeebnet, damit die Verteidigungswälle errichtet werden konnten."}]'::jsonb, ''),
  ('schillaplotz', 'Schillaplotz', '', '', '', '', 'Schillerplatz', '[{"kategorie": "allg.", "text": "historisch und kulturell bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Der Platz liegt westlich der [[Ringstraße]] und wurde nach dem berühmten deutschen Dichter und Dramatiker Friedrich Schiller benannt"}, {"kategorie": "", "text": "Im Zentrum des Platzes und des umgebenden Schillerparks steht ein Denkmal zu Ehren Schillers, das 1876 errichtet wurde"}, {"kategorie": "", "text": "Am Schillerplatz befindet sich auch die [[Akademie]] der bildenden Künste Wien, eine der ältesten und renommiertesten Kunsthochschulen Europas."}]'::jsonb, ''),
  ('opangossn', 'Opangossn', '', '', '', '', 'Operngasse', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die sich bis in den 4. Bezirk ([[Wieden]]) erstreckt\""}, {"kategorie": "", "text": "Auf dem Areal der ehemaligen Kärntner Bastei (später [[Augustinerbastei]]), wurde 1861 eine neue Straße eröffnet. Im gleichen Jahr wurde die Staatsoper erbaut (1861-1868). Nach ihr erhielt die neue Gasse ihren Namen"}, {"kategorie": "", "text": "Die Operngasse beginnt am [[Albertinaplatz]] und endet im 4. Bezirk bei der [[Schleifmühlgasse]]"}, {"kategorie": "", "text": "Die Straße führt direkt an der [[Wiener]] Staatsoper vorbei und verbindet zentrale Bereiche der Stadt mit dem nahe gelegenen [[Naschmarkt]] und der [[Technischen]] Universität Wien."}]'::jsonb, ''),
  ('daumpfschiffschdrossn', 'Daumpfschiffschdrossn', '', '', '', '', 'Dampfschiffstraße', '[{"kategorie": "allg.", "text": "ruhige Straße im [[Weißgerberviertel]] im 3. Wiener Gemeindebezirk ([[Landstraße]])"}, {"kategorie": "", "text": "Sie ist benannt nach dem Direktions- und Betriebsgebäude der Donaudampfschifffahrtsgesellschaft, welches sich von 1838 bis 1981 hier befand"}, {"kategorie": "", "text": "Im 19. Jahrhundert war der [[Donaukanal]] eine wichtige Wasserstraße für den Güter- und Personenverkehr in Wien. Damals waren Dampfschiffe eine der modernsten und effizientesten Fortbewegungsmethoden auf dem Wasser. Die Dampfschiffstraße lag einst in der Nähe zahlreicher Anlegestellen und Einrichtungen für die Dampfschifffahrt, die entlang des Kanals betrieben wurden"}, {"kategorie": "", "text": "Heute ist die Dampfschiffstraße Teil eines urbanen Gebiets, das im Laufe der Jahre stark modernisiert wurde. Sie hat in der Gegenwart keine direkte Verbindung mehr zur Schifffahrt, doch der Name bleibt ein Hinweis auf die industrielle und verkehrstechnische Bedeutung des Donaukanals in früheren Zeiten."}]'::jsonb, ''),
  ('marxagossn', 'Marxagossn', '', '', '', '', 'Marxergasse', '[{"kategorie": "allg.", "text": "\"stark frequentierte Straße im 3. Wiener Gemeindebezirk ([[Landstraße]])\""}, {"kategorie": "", "text": "Die Marxergasse bildet die Abgrenzung des alten [[Weißgerberviertels]] gegen den städtebaulichen Raum der [[Landstraßer]] Hauptstraße und verbindet den [[Wienfluss]] mit dem [[Donaukanal]]"}, {"kategorie": "", "text": "Sie wurde 1910 nach dem Weihbischof Anton Marxer (1703-1775) benannt. Marxer war ab 1753 Domprobst und galt als Förderer des Landstraßer Waisenhauses"}, {"kategorie": "", "text": "Die Marxergasse entwickelte sich im 19. Jahrhundert zu einer wichtigen Verbindungsstraße im Bezirk Landstraße, insbesondere nachdem die Gegend durch den Bau von Bahnanlagen und der Wiener Stadtbahn (heute S-Bahn und U-Bahn) aufgewertet wurde. Der [[Bahnhof]] Wien Mitte, einer der größten Verkehrsknotenpunkte der Stadt, liegt unweit der Marxergasse"}, {"kategorie": "", "text": "Heute ist die Marxergasse eine stark frequentierte Straße, die sowohl Wohn- als auch Bürogebäude beherbergt."}]'::jsonb, ''),
  ('hellwagschdrossn', 'Hellwagschdrossn', '', '', '', '', 'Hellwagstraße', '[{"kategorie": "allg.", "text": "Straße im 20. Wiener Gemeindebezirk ([[Brigittenau]]), die nach Albert Hellwag, einem bedeutenden österreichischen Eisenbahningenieur, benannt wurde (Erbauer der Nordwestbahn und des St.-Gotthard-Tunnels)"}, {"kategorie": "", "text": "Sie verläuft in der Nähe des historischen Nordbahnhofgeländes, einem einst wichtigen Eisenbahnknotenpunkt Wiens"}, {"kategorie": "", "text": "Der [[Nordbahnhof]] war einst der größte Bahnhof der Stadt und spielte eine zentrale Rolle im Güter- und Personenverkehr. Durch die Nähe zu diesem Bahnhof und die Bedeutung der Eisenbahn im 19. Jahrhundert wurde die Hellwagstraße zu einem wichtigen Standort für die Eisenbahnindustrie"}, {"kategorie": "", "text": "Heute befindet sich die Hellwagstraße in einem überwiegend städtischen Wohngebiet, das in den letzten Jahren stark modernisiert wurde. Unter der Straße verläuft von ihrem Beginn bis zur Nordbahn die hier 1996 eröffnete Verlängerung der U-Bahn-Linie U6 nach [[Floridsdorf]]."}]'::jsonb, ''),
  ('leysaschdrossn', 'Leysaschdrossn', '', '', '', '', 'Leyserstraße', '[{"kategorie": "allg.", "text": "\"gut angebundene Wohnstraße im [[Stadtteil]] Breitensee im 14. Wiener Gemeindebezirk ([[Penzing]]), die sowohl historische als auch städtebauliche Bedeutung hat\""}, {"kategorie": "", "text": "Sie erstreckt sich in einem weitgehend ruhigen Wohngebiet und ist nach nach Zeugmeister Ulrich Leyser benannt, der sich während der Türkenbelagerung 1529 Verdienste erworben hat und für seine besondere Tapferkeit ausgezeichnet wurde"}, {"kategorie": "", "text": "Die Straße ist Teil eines der typischen Wohnviertel Wiens, das sich im Laufe des 20. Jahrhunderts stetig entwickelt hat. Historisch gesehen hat sich die Straße im 20. Jahrhundert von einer Randlage zu einem attraktiven Wohngebiet entwickelt, besonders durch die Expansion der Stadt Wien nach Westen."}]'::jsonb, ''),
  ('wincklmaunnschdrossn', 'Wincklmaunnschdrossn', '', '', '', '', 'Winckelmannstraße', '[{"kategorie": "allg.", "text": "\"Straße im 15. Wiener Gemeindebezirk ([[Rudolfsheim-Fünfhaus]]), die nach dem deutschen Archäologen und Kunsthistoriker Johann Joachim Winckelmann (1717–1768) benannt ist\""}, {"kategorie": "", "text": "Winckelmann gilt als Begründer der modernen Archäologie und Kunstgeschichte und war ein bedeutender Vordenker des [[Klassizismus]]"}, {"kategorie": "", "text": "Er war einer der einflussreichsten Gelehrten seiner Zeit und förderte die Wertschätzung der antiken griechischen und römischen Kunst in Europa"}, {"kategorie": "", "text": "Aufgrund ihrer Nähe zu wichtigen kulturellen und historischen Orten wie dem [[Technischen]] Museum Wien und dem [[Schloss]] Schönbrunn bietet sie eine gute Wohnlage für Menschen, die sowohl städtisches Leben als auch Zugang zu kulturellen Einrichtungen suchen"}]'::jsonb, ''),
  ('tegetthoffschdrossn', 'Tegetthoffschdrossn', '', '', '', '', 'Tegetthoffstraße', '[{"kategorie": "allg.", "text": "\"zentrale Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die nach dem berühmten österreichischen Admiral Wilhelm von Tegetthoff (1827–1871) benannt ist\""}, {"kategorie": "", "text": "Wilhelm von Tegetthoff (1827-1871) war der bedeutendste Admiral, den die österreichisch-ungarische Kriegsmarine hervorgebracht hatte. Neben zahlreichen anderen erfolgreichen Schlachten ist besonders die Seeschlacht bei Lissa (heute Kroatien) hervorzuheben"}, {"kategorie": "", "text": "Er unternahm auch Forschungsreisen, wie 1867 nach Nordamerika, die er unterbrechen musste, um den Leichnam des [[Kaisers]] Maximilian von Mexiko heim zu bringen"}, {"kategorie": "", "text": "Sie verläuft nahe bedeutender Sehenswürdigkeiten wie der [[Albertina]], der [[Wiener]] Staatsoper und dem [[Hotel]] Sacher"}, {"kategorie": "", "text": "Die Tegetthoffstraße liegt in einem der historisch und kulturell reichsten Teile Wiens. Ihre zentrale Lage und ihre Nähe zu wichtigen Sehenswürdigkeiten machen sie zu einem beliebten Ausgangspunkt für Stadtbesichtigungen."}]'::jsonb, ''),
  ('lobkowitzplotz', 'Lobkowitzplotz', '', '', '', '', 'Lobkowitzplatz', '[{"kategorie": "allg.", "text": "\"historisch bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)\""}, {"kategorie": "", "text": "Der Platz liegt im Herzen Wiens, in der Nähe der [[Wiener]] Staatsoper und des [[Burggartens]]"}, {"kategorie": "", "text": "Der Platz trägt seinen Namen zu Ehren der Fürsten Lobkowitz, insbesondere nach Fürst Franz Joseph Maximilian von Lobkowitz (1772–1816), einem bedeutenden Kunstmäzen und Musikliebhaber. Die Familie war bekannt für ihre Unterstützung der Künste, und Fürst Franz Joseph war ein enger Freund und Förderer von Ludwig van Beethoven. Das nahegelegene [[Palais]] Lobkowitz diente der Familie als Wiener Residenz und ist heute Teil des [[Theatermuseums]]"}, {"kategorie": "", "text": "Heute ist der Lobkowitzplatz ein ruhiger und malerischer Ort in der belebten Wiener Innenstadt."}]'::jsonb, ''),
  ('teatamuseum', 'Teatamuseum', '', '', '', '', 'Theatermuseum', '[{"kategorie": "allg.", "text": "\"bedeutendes Museum in Wien, das sich der Geschichte und Kultur des Theaters widmet\""}, {"kategorie": "", "text": "Es befindet sich im historischen [[Palais]] Lobkowitz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt) und bietet einen umfassenden Einblick in die Welt des Theaters, von seinen Ursprüngen bis zur Gegenwart"}, {"kategorie": "", "text": "Das Theatermuseum wurde 1975 gegründet und ist eine Institution der Österreichischen Nationalbibliothek. Es entstand aus der Zusammenführung mehrerer Sammlungen zur Theatergeschichte, darunter Bühnenbilder, Kostüme, Manuskripte, und Requisiten. Seit 1991 befindet sich das Museum im barocken Palais Lobkowitz, das selbst eine lange kulturelle Tradition aufweist, da es eng mit der Musik- und Kunstgeschichte Wiens verknüpft ist"}, {"kategorie": "", "text": "Das Theatermuseum beherbergt eine der umfangreichsten Sammlungen zur Theatergeschichte in Europa. Die Bestände umfassen über eine Million Objekte, darunter (i) Kostüme und Bühnenbilder (historische Theaterkostüme, Entwürfe und Modelle für Bühnenbilder sowie originale Bühnenbilder, die die Entwicklung der Theaterkunst über die Jahrhunderte hinweg dokumentieren), (ii) Requisiten und Masken (eine Sammlung von Theaterrequisiten, Masken und Marionetten, die Einblicke in die Inszenierung und die Schauspielkunst bieten), (iii) Manuskripte und Dokumente (Theatermanuskripte, Korrespondenzen, Verträge und Programmhefte, die die organisatorischen und kreativen Prozesse hinter den Aufführungen veranschaulichen), sowie (iv)\nGemälde und Porträts (die umfangreiche Gemäldesammlung zeigt Porträts von Schauspielern, Dramatikern und Theaterpersönlichkeiten sowie Szenen aus berühmten Aufführungen)"}, {"kategorie": "", "text": "Das Theatermuseum in Wien ist eines der bedeutendsten Museen für Theatergeschichte in Europa und wichtiger Bestandteil der Wiener Kulturlandschaft."}]'::jsonb, ''),
  ('fuehrichgossn', 'Führichgossn', '', '', '', '', 'Führichgasse', '[{"kategorie": "allg.", "text": "kurze, aber bedeutende Straße im 1. Wiener Gemeindebezirk ([[Innere]] Stadt)"}, {"kategorie": "", "text": "Sie verbindet den [[Albertinaplatz]] mit der [[Tegetthoffstraße]] und ist nach dem österreichischen Maler und Grafiker Joseph Ritter von Führich (1800–1876) benannt, der zu den bekanntesten Künstlern der Biedermeierzeit zählt und vor allem für seine religiösen Werke und Fresken bekannt ist"}, {"kategorie": "", "text": "Führich war Professor an der Akademie der bildenden Künste Wien und gehörte zu den zentralen Figuren der Kunstszene im 19. Jahrhundert. Sein künstlerisches Werk trug wesentlich zur Entwicklung der religiösen Kunst in Österreich bei"}, {"kategorie": "", "text": "Die Führichgasse liegt im Herzen der Wiener Innenstadt und ist durch ihre Nähe zu bedeutenden Sehenswürdigkeiten wie der [[Albertina]], der [[Wiener]] Staatsoper und dem [[Hotel]] Sacher geprägt"}, {"kategorie": "", "text": "Sie ist von prachtvollen Gebäuden im Stil der [[Gründerzeit]] und des [[Klassizismus]] umgeben, die zur reichen architektonischen Vielfalt der Wiener Innenstadt beitragen."}]'::jsonb, ''),
  ('albertinaplotz', 'Albertinaplotz', '', '', '', '', 'Albertinaplatz', '[{"kategorie": "allg.", "text": "\"bedeutender Platz im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), in unmittelbarer Nähe zur [[Albertina]], einem der wichtigsten Kunstmuseen der Stadt\""}, {"kategorie": "", "text": "Der Albertinaplatz hat eine lange Geschichte, die eng mit der Albertina und dem [[Augustinerkloster]] verbunden ist. Ursprünglich war das Gebiet Teil der [[Wiener]] Stadtmauer, bis diese im 19. Jahrhundert abgerissen wurde, um Platz für die Stadterweiterung zu schaffen. Der Platz erhielt seinen Namen nach dem Herzog Albert von Sachsen-Teschen, dem Gründer der Albertina und einem der wichtigsten Kunstsammler seiner Zeit"}, {"kategorie": "", "text": "Eines der auffälligsten Monumente auf dem Albertinaplatz ist das von Alfred Hrdlicka entworfene \"Denkmal gegen Krieg und Faschismus\", das an die Opfer des Nationalsozialismus und des Zweiten Weltkriegs erinnert. Es besteht aus mehreren Teilen, darunter die Skulptur des knienden „Straßenwaschers“ und die „Tore der Gewalt“"}, {"kategorie": "", "text": "Der Albertinaplatz liegt strategisch günstig zwischen der [[Wiener]] Staatsoper, der [[Kärntner]] Straße und dem [[Burggarten]] und bildet einen Knotenpunkt für Besucher, die das kulturelle und architektonische Erbe Wiens erkunden möchten."}]'::jsonb, ''),
  ('augustinakloosta', 'Augustinakloosta', '', '', '', '', 'Augustinerkloster', '[{"kategorie": "allg.", "text": "\"historisch bedeutendes Kloster im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), das zum Augustinerorden gehört\""}, {"kategorie": "", "text": "Es ist eng verbunden mit der benachbarten [[Augustinerkirche]], die als kaiserliche Hofpfarrkirche diente"}, {"kategorie": "", "text": "Das Kloster und die Kirche befinden sich in der Nähe der [[Albertina]] sowie unweit der [[Wiener]] Hofburg und spielten über Jahrhunderte hinweg eine wichtige Rolle im religiösen und politischen Leben Wiens"}, {"kategorie": "", "text": "Durch die Nähe zur Hofburg wurde das Augustinerkloster von den Habsburgern stark gefördert, und die Augustinerkirche diente über Jahrhunderte hinweg als Hof- und Ordenskirche. Sie war Schauplatz zahlreicher historischer Ereignisse, darunter königliche Hochzeiten und Beerdigungen. Die enge Verbindung zur Habsburger Dynastie verlieh dem Kloster große Bedeutung"}, {"kategorie": "", "text": "Das Augustinerkloster ist ein klassisches Beispiel mittelalterlicher Klosterarchitektur. Es besteht aus mehreren Gebäudeteilen, die um Höfe und Gärten gruppiert sind. Im Laufe der Jahrhunderte wurde das Kloster mehrfach erweitert und umgebaut, doch viele der ursprünglichen gotischen Strukturen sind noch erhalten"}, {"kategorie": "", "text": "Das Augustinerkloster ist auch heute noch aktiv und beherbergt Mönche des Augustinerordens. Derzeit beherbergt es den Konvent von drei Augustinern, die sich der wichtigen Aufgabe stellen, den Augustinerorden in Österreich wieder aufzubauen bzw. zu stärken"}]'::jsonb, ''),
  ('heazgruft', 'Heazgruft', '', '', '', '', 'Herzgruft', '[{"kategorie": "allg.", "text": "\"besondere Begräbnisstätte in der [[Augustinerkirche]] im 1. Wiener Gemeindebezirk ([[Innere]] Stadt), die zur Aufbewahrung der Herzen verstorbener Mitglieder des Habsburgerhauses dient\""}, {"kategorie": "", "text": "Die Herzgruft ist Teil der sogenannten Herzbestattungen, einer Tradition der Habsburger, bei der die Herzen der verstorbenen Familienmitglieder separat vom Körper beigesetzt wurden. Die Leichname selbst wurden meist in der [[Kapuzinergruft]] bestattet, während die Herzen in der Herzgruft ruhen"}, {"kategorie": "", "text": "Die Herzgruft wurde im Jahr 1627 von Kaiser [[Ferdinand]] III. begründet, als die Habsburger begannen, ihre Herzen separat in der Augustinerkirche bestatten zu lassen. Diese Tradition sollte die enge Bindung der Habsburger an den katholischen Glauben und ihre geistliche Hingabe symbolisieren. Sie war auch Ausdruck des mittelalterlichen Glaubens, dass das Herz als Sitz der Seele besondere Verehrung verdiene"}, {"kategorie": "", "text": "Insgesamt sind die Herzen von 54 Mitgliedern der Habsburgerdynastie in silbernen Urnen in der Herzgruft aufbewahrt, darunter auch die Herzen berühmter Kaiser und Könige wie [[Kaiser]] Franz I., [[Kaiserin]] Maria Theresia und [[Kaiser]] Franz Joseph I."}, {"kategorie": "", "text": "Die Herzgruft befindet sich im Loretokapellchen der Augustinerkirche, die an das Augustinerkloster angeschlossen ist. Dieses kleine, unscheinbare Kapellchen beherbergt die silbernen Urnen mit den Herzen der Habsburger, die in Nischen entlang der Wände aufbewahrt werden"}, {"kategorie": "", "text": "Die Urnen, die die Herzen enthalten, sind aus Silber und mit den Namen der Verstorbenen sowie Daten der Bestattung versehen. Obwohl die Herzgruft nicht so prächtig gestaltet ist wie andere Habsburger-Gräber, liegt ihr Wert vor allem in ihrer symbolischen und historischen Bedeutung."}]'::jsonb, ''),
  ('innschdrossn', 'Innschdrossn', '', '', '', '', 'Innstraße', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), die nach dem Fluss Inn benannt wurde, einem wichtigen Nebenfluss der Donau, der durch die Schweiz, Österreich und Deutschland fließt\""}, {"kategorie": "", "text": "Die Straße befindet sich in einem Wohn- und Geschäftsviertel und spiegelt die in Wien häufige Praxis wider, Straßen nach Flüssen oder geographischen Orten zu benennen"}, {"kategorie": "", "text": "An der Stelle des Hauses Nummer 6 stand bis 1905 eine Johannes-Nepomuk-Kapelle, bei der die tschechischen Bewohner Zwischenbrückens Abendandachten verrichteten"}, {"kategorie": "", "text": "Auf Höhe von Hausnummer 21 befand sich zwischen 1942 und 1945 ein Zwangsarbeiterlager"}, {"kategorie": "", "text": "Die Innstraße liegt im nördlichen Teil der Leopoldstadt und verläuft parallel zu anderen Straßen, die ebenfalls nach Flüssen oder geographischen Merkmalen benannt sind, wie der [[Donaueschingenstraße]] und der [[Marchfeldstraße]]."}]'::jsonb, ''),
  ('donaueschingenschdrossn', 'Donaueschingenschdrossn', '', '', '', '', 'Donaueschingenstraße', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), die nach der Stadt Donaueschingen in Deutschland benannt, welche als einer der Quellorte der Donau gilt\""}, {"kategorie": "", "text": "Die Benennung der Straße spiegelt die in Wien übliche Praxis wider, Straßen nach Flüssen, geografischen Orten oder Städten zu benennen, die eine historische oder symbolische Verbindung zur Region haben"}, {"kategorie": "", "text": "Donaueschingen ist eine Stadt im Schwarzwald-Baar-Kreis in Baden-Württemberg, Deutschland, die als Quellstadt der Donau bekannt ist. Dort befinden sich die Donauquellen, die als Ursprung des Flusses gelten, der eine zentrale Rolle für Wien und viele andere europäische Städte spielt. Die Donaueschingenstraße in Wien wurde nach diesem bedeutenden Ort benannt, um die Verbindung zur Donau zu betonen"}, {"kategorie": "", "text": "Die Donaueschingenstraße liegt im nördlichen Teil des Bezirks [[Leopoldstadt]] und befindet sich in einem ruhigen Wohnviertel. Sie verläuft in der Nähe anderer Straßen, die ebenfalls nach Flüssen oder geografischen Orten benannt sind, wie die [[Innstraße]] oder der [[Marchfeldstraße]]."}]'::jsonb, ''),
  ('marchfoedschdrossn', 'Marchfödschdrossn', '', '', '', '', 'Marchfeldstraße', '[{"kategorie": "allg.", "text": "\"ruhige Wohnstraße im 2. Wiener Gemeindebezirk ([[Leopoldstadt]]), die nach dem Marchfeld, einer fruchtbaren Ebene im Nordosten Niederösterreichs, benannt ist\""}, {"kategorie": "", "text": "Das Marchfeld spielte historisch eine wichtige Rolle für die Versorgung Wiens mit landwirtschaftlichen Produkten, ist eine der bedeutendsten Agrarlandschaften Österreichs und galt einst als \"Kornkammer Wiens\". Die Benennung der Straße verweist somit auf die enge Verbindung Wiens zur umliegenden Region und ihren wirtschaftlichen Beitrag zur Stadt"}, {"kategorie": "", "text": "Die Straße liegt in einem gut angebundenen Wohngebiet nahe der [[Donau]] und unweit des [[Praters]]. Die Nähe zum [[Praterstern]], einem wichtigen Verkehrsknotenpunkt mit U-Bahn-, Straßenbahn- und S-Bahn-Anschluss, sorgt für eine gute öffentliche Verkehrsanbindung."}]'::jsonb, ''),
  ('schdroomschdrossn', 'Schdroomschdrossn', '', '', '', '', 'Stromstraße', '[{"kategorie": "allg.", "text": "zentrale Straße im 20. Wiener Gemeindebezirk ([[Brigittenau]]), die zwischen [[Donau]] und [[Donaukanal]] verläuft"}, {"kategorie": "", "text": "Die Straße wurde nach ihrer Lage benannt. Der Begriff \"Strom\" ist eine historische Bezeichnung für größere Flüsse oder Ströme, und in diesem Fall weist der Name der Straße auf die Bedeutung der Donau und des Donaukanals als Wasserstraßen hin, die einst eine zentrale Rolle im Gütertransport und in der städtischen Wasserversorgung spielten"}, {"kategorie": "", "text": "Heute ist die Stromstraße eine zentrale Verkehrsader im 20. Wiener Bezirk und eine der Hauptverkehrsstraßen im Bezirk [[Brigittenau]]."}]'::jsonb, ''),
  ('wehlischdrossn', 'Wehlischdrossn', '', '', '', '', 'Wehlistraße', '[{"kategorie": "allg.", "text": "Hauptverkehrsstraße im 2. und 20. Wiener Gemeindebezirk ([[Leopoldstadt]] und [[Brigittenau]]), die parallel zur [[Donau]] verläuft"}, {"kategorie": "", "text": "Sie ist nach dem Vizepräsidenten der Donauregulierungskommission, August Freiherr von Wehli (1810-1892) benannt"}, {"kategorie": "", "text": "Der [[Handelskai-Bahnhof]], ein wichtiger Verkehrsknotenpunkt für den Regional- und Fernverkehr, liegt direkt an der Wehlistraße, was sie zu einer strategisch wichtigen Verkehrsader macht. Für den Autoverkehr bietet die Wehlistraße direkten Zugang zu wichtigen Brücken wie der [[Reichsbrücke]] und den Autobahnen, die nach Norden und Osten führen"}, {"kategorie": "", "text": "Die Wehlistraße ist auch ein wichtiger Standort für städtische Einrichtungen und dient als Zugang zu beliebten Erholungsgebieten entlang der Donau, wie dem [[Donauinsel-Freizeitgebiet]]."}]'::jsonb, ''),
  ('kolschitzkygossn', 'Kolschitzkygossn', '', '', '', '', 'Kolschitzkygasse', '[{"kategorie": "allg.", "text": "\"Straße im 4. Wiener Gemeindebezirk ([[Wieden]]), die nach Georg Franz Kolschitzky (1640–1694) benannt wurde\";  2.Die Kolschitzkygasse ehrt Georg Franz Kolschitzky, einen polnisch-ukrainischen Abenteurer und Dolmetscher, der eine Rolle während der Befreiung Wiens im Jahr 1683 spielte. Der Legende nach soll Kolschitzky im Zuge der 2. Türkenbelagerung Wiens eine wichtige Botennachricht durch die feindlichen Linien der Osmanen an die Wiener Truppen überbracht haben. Als Belohnung erhielt er später angeblich einen Sack mit zurückgelassenen Kaffeebohnen und eröffnete Wiens erstes Kaffeehaus. Diese Geschichte hat Kolschitzky in die Wiener Folklore eingebracht und ihn zu einer Symbolfigur der Wiener [[Kaffeehauskultur]] gemacht"}, {"kategorie": "", "text": "Die Gegend um die Kolschitzkygasse ist durch eine Mischung aus Wohn- und Geschäftsgebäuden sowie historischen Gebäuden geprägt. Der 4. Bezirk ist bekannt für seine elegante Architektur und seine zentrale Lage, was ihn zu einem begehrten Wohn- und Geschäftsviertel macht."}]'::jsonb, ''),
  ('bibahaufnweg', 'Bibahaufnweg', '', '', '', '', 'Biberhaufenweg', '[{"kategorie": "allg.", "text": "\"Straße im 22. Wiener Gemeindebezirk ([[Donaustadt]]), die in einem modernen Wohngebiet liegt und eine gute Anbindung an das Verkehrsnetz sowie Zugang zu den weitläufigen Erholungsgebieten im Bezirk bietet\""}, {"kategorie": "", "text": "Sie nach dem Biberhaufen, einer ehemaligen Donauinsel mit reichem Biberbestand, benannt"}, {"kategorie": "", "text": "Wie viele Straßen in Donaustadt erinnert er an die ländliche und natürliche Geschichte des Gebiets, das früher vorwiegend aus Au- und Sumpfgebieten bestand. Die Benennung solcher Straßen nach geographischen Besonderheiten oder Tierarten spiegelt die Verbindung des Bezirks zu seiner natürlichen Umgebung wider."}]'::jsonb, ''),
  ('engerthschdrossn', 'Engerthschdrossn', '', '', '', '', 'Engerthstraße', '[{"kategorie": "allg.", "text": "eine der wichtigsten Verkehrsstraßen in Wien, die durch den 2. und 20. Wiener Gemeindebezirk ([[Leopoldstadt]] und [[Brigittenau]]) verläuft"}, {"kategorie": "", "text": "Die Engerthstraße wurde zu Ehren von Wilhelm von Engerth benannt, einem bedeutenden Ingenieur, der maßgeblich an der Entwicklung der Eisenbahntechnik beteiligt war"}, {"kategorie": "", "text": "Engerth konstruierte eine Gebirgslokomotive für die Semmeringbahn und war entscheidend an der Wahl des Streckenverlaufs der Arlbergbahn beteiligt. 1869 erhielt der Träger zahlreicher in- und ausländischer Orden den Titel Hofrat, 1874 wurde er ins ins Herrenhaus gewählt"}, {"kategorie": "", "text": "1872 erfand er ein Schwimmtor an der [[Schleuse]] Nußdorf, das im Volksmund \"Sperrschiff\" genannt wurde, und das das Eindringen von Hochwasser und Treibeis in den Donaukanal und die damit zusammenhängende Überschwemmungsgefahr verhindern sollte"}, {"kategorie": "", "text": "Die Engerthstraße verläuft parallel zur [[Donau]] und bildet eine wichtige Ost-West-Verbindung in diesem Teil der Stadt. Sie weist eine teilweise spätgründerzeitliche Verbauung auf, wird jedoch von großen städtischen Wohnhausanlagen der Zwischen- und Nachkriegszeit dominiert."}]'::jsonb, ''),
  ('siccardsbuaggossn', 'Siccardsbuaggossn', '', '', '', '', 'Siccardsburggasse', '[{"kategorie": "allg.", "text": "\"Straße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die nach dem österreichischen Architekten August Sicard von Siccardsburg (1813–1868) benannt ist\""}, {"kategorie": "", "text": "Sicard von Siccardsburg war gemeinsam mit Eduard van der Nüll einer der bedeutendsten Architekten des 19. Jahrhunderts in Wien und ebenfalls ein prominenter Vertreter des Wiener [[Historismus]]. Gemeinsam entwarfen sie einige der bekanntesten Gebäude Wiens, darunter die [[Wiener]] Staatsoper"}, {"kategorie": "", "text": "Die Siccardsburggasse ist eine Wohnstraße, umgeben von typischen Wiener Zinshäusern, kleineren Geschäften und einigen Bildungseinrichtungen"}, {"kategorie": "", "text": "Der Bezirk [[Favoriten]] hat sich in den letzten Jahrzehnten stark entwickelt und ist durch seine Nähe zum [[Hauptbahnhof]] Wien sowie zu großen Erholungsgebieten wie dem [[Böhmischen]] Prater ein beliebter Wohnort. Der Bezirk steht auch im Fokus städtebaulicher Modernisierungen, die das Bild des Stadtteils prägen."}]'::jsonb, ''),
  ('leebgossn', 'Leebgossn', '', '', '', '', 'Leebgasse', '[{"kategorie": "allg.", "text": "\"Straße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die nach dem ehemaligen Wiener Bürgermeister Anton Josef Edler von Leeb (1769-1837) benannt ist\""}, {"kategorie": "", "text": "Die Bestellung zum Bürgermeister erreichte Leeb durch eine Reihe von Zufällen. Im September 1834 wurde Bürgermeister Anton Lumpert zum Rücktritt veranlasst. Der eigentlich als Nachfolger vorgesehene Ignaz Czapka war ein Protegée von Kaiser [[Franz]] I. gewesen, der aber verstarb. Somit hatte Czapka unter dem neuen Kaiser [[Ferdinand]] I. keine Chance mehr auf eine Bestellung. Dadurch fiel die Wahl nun auf Anton Josef Leeb mittels allerhöchstem Entschluss vom 31. März 1835 und Regierungsdekret vom 7. April 1835"}, {"kategorie": "", "text": "In der kurzen Amtszeit Leebs wurde mit dem Bau der [[Kaiser-Ferdinands-Wasserleitung]] begonnen, die bis zur Errichtung der ersten [[Hochquellenwasserleitung]] das am weitesten verzweigte Rohrnetz zur Wasserversorgung in der Stadt Wien war. Gewonnen wurde damals das Grundwasser im Uferbereich des [[Donaukanals]] in der [[Spittelau]]"}, {"kategorie": "", "text": "Die Leebgasse liegt im südlichen Teil des 10. Bezirks ([[Favoriten]]), einem dicht besiedelten Wiener Bezirk, der von Wohngebieten, Schulen und kleineren Gewerbegebieten geprägt ist. Die Straße ist eine typische Wohnstraße, die hauptsächlich von Zinshäusern und einigen Geschäften gesäumt wird. Favoriten selbst ist einer der größten und bevölkerungsreichsten Bezirke Wiens, der sich in den letzten Jahren durch städtebauliche Entwicklungen und seine multikulturelle Bevölkerung hervorgetan hat."}]'::jsonb, ''),
  ('trostschdrossn', 'Trostschdrossn', '', '', '', '', 'Troststraße', '[{"kategorie": "allg.", "text": "\"bedeutende Straße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die sich von der [[Favoritenstraße]] bis zur [[Triesterstraße]] erstreckt\""}, {"kategorie": "", "text": "Sie ist nach nach dem Fleischhauer, Hausbesitzer und Gemeinderat (1875-1893) Michael Trost benannt"}, {"kategorie": "", "text": "Die Troststraße liegt im zentralen Teil des Bezirks Favoriten und durchquert ein dicht besiedeltes, urbanes Gebiet. Sie ist von Wohngebäuden, Geschäften und öffentlichen Einrichtungen gesäumt, was sie zu einer wichtigen Lebensader in diesem Teil von Favoriten macht"}, {"kategorie": "", "text": "Mit der Eröffnung der U-Bahn-Station Troststraße wurde die Straße noch stärker in das städtische Verkehrsnetz integriert und hat an Bedeutung als Verbindungsstraße innerhalb des Bezirks und darüber hinaus gewonnen."}]'::jsonb, ''),
  ('alxingagossn', 'Alxingagossn', '', '', '', '', 'Alxingergasse', '[{"kategorie": "allg.", "text": "\"Straße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die nach dem österreichischen Schriftsteller und Dichter Johann Baptist von Alxinger (1755–1797) benannt ist\""}, {"kategorie": "", "text": "Alxinger war im 18. Jahrhundert ein bekannter Literat der Aufklärung und bekannt für seine Gedichte und Dramen"}, {"kategorie": "", "text": "Alxinger stand in engem Kontakt mit literarischen Kreisen der damaligen Zeit, darunter Persönlichkeiten wie Christoph Martin Wieland. Seine Werke spiegeln die Ideen und Ideale der Aufklärung wider"}, {"kategorie": "", "text": "Die Alxingergasse verläuft im südlichen Teil des 10. Bezirks ([[Favoriten]]), einem der bevölkerungsreichsten Bezirke Wiens. Sie ist eine typische Wohnstraße und befindet sich in einem dicht besiedelten Gebiet mit einer Mischung aus Wohnhäusern, Geschäften und öffentlichen Einrichtungen."}]'::jsonb, ''),
  ('gussriiglschdrossn', 'Gussriiglschdrossn', '', '', '', '', 'Gußriegelstraße', '[{"kategorie": "allg.", "text": "\"Straße im 10. Wiener Gemeindebezirk ([[Favoriten]]), die nach einem historischen Flurnamen benannt ist\""}, {"kategorie": "", "text": "Der Begriff \"Gußriegel\" stammt aus der ländlichen Vergangenheit des Bezirks und bezeichnete ursprünglich einen schmalen Landstreifen oder ein Flurstück"}, {"kategorie": "", "text": "Die Benennung nach Flurnamen ist in Wien, insbesondere in den äußeren Bezirken, nicht unüblich und spiegelt die landwirtschaftliche Geschichte wider, bevor diese Gebiete urbanisiert wurden"}, {"kategorie": "", "text": "Die Gußriegelstraße verläuft in einer typischen Wohngegend, die von Wohnblöcken, Schulen und kleineren Geschäften geprägt ist."}]'::jsonb, ''),
  ('dannebeagplotz', 'Dannebeagplotz', '', '', '', '', 'Dannebergplatz', '[{"kategorie": "allg.", "text": "\"zentraler Platz im 3. Wiener Gemeindebezirk ([[Landstraße]]), der nach dem österreichischen Politiker Robert Danneberg (1882–1942) benannt ist, einem bedeutenden sozialdemokratischen Politiker der Ersten Republik\""}, {"kategorie": "", "text": "Danneberg spielte eine zentrale Rolle in der Wiener Kommunalpolitik und war maßgeblich an der Gestaltung des à„Roten Wien“ beteiligt, einer Ära, in der die Stadtverwaltung unter sozialdemokratischer Führung stand und zahlreiche soziale Reformen und Wohnbauprojekte umgesetzt wurden"}, {"kategorie": "", "text": "Danneberg war Mitglied des Wiener Gemeinderats, des Nationalrats und später des Wiener Landtags. Er gilt als einer der wichtigsten Architekten des sozialen Wohnbaus in Wien, der die Entwicklung des à„Roten Wien“ in den 1920er und 1930er Jahren prägte"}, {"kategorie": "", "text": "Nach dem „Anschluss“ Österreichs wurde er 1938 von den Nationalsozialisten verhaftet und 1942 im KZ Auschwitz ermordet"}, {"kategorie": "", "text": "Der Dannebergplatz liegt unweit der [[Landstraßer]] Hauptstraße, einer der Hauptverkehrs- und Einkaufsstraßen im Bezirk"}, {"kategorie": "", "text": "Der Platz selbst ist eine grüne, parkähnliche Anlage, die den Anwohnern und Besuchern eine Möglichkeit zur Erholung bietet. Rund um den Dannebergplatz gibt es Schulen, Nahversorger und öffentliche Einrichtungen, was ihn zu einem wichtigen sozialen Treffpunkt im Bezirk macht."}]'::jsonb, '')
